    class DummyJsonFactory:
        _documents: dict[object, object] = {}
        _persisted_documents: dict[object, object] = {}
        _account_documents: dict[tuple[str, str], object] = {}
        _save_calls: dict[object, int] = {}
        _save_results: dict[object, bool] = {}
        _reload_overrides: dict[object, object] = {}
        _operation_log: list[tuple[str, str]] = []
        _apply_calls: list[tuple[str, str, object, str]] = []

        def __init__(self, name: str, scope: str = "account"):
            self.name = str(name)
            self.scope = str(scope)

        @classmethod
        def _is_standalone_profile_name(cls, name: str) -> bool:
            normalized_name = str(name or "").replace("\\", "/")
            return normalized_name.startswith("Widgets/MerchantRules/Profiles/") and normalized_name.casefold().endswith(".json")

        def _standalone_physical_path(self) -> Path:
            owner = "global" if self.scope == "global" else "merchant.rules@example.com"
            return project_root / "json" / owner / Path(self.name.replace("/", os.sep))

        def _is_standalone_profile(self) -> bool:
            return self._is_standalone_profile_name(self.name)

        @classmethod
        def reset(cls) -> None:
            cls._documents.clear()
            cls._persisted_documents.clear()
            cls._account_documents.clear()
            cls._save_calls.clear()
            cls._save_results.clear()
            cls._reload_overrides.clear()
            cls._operation_log.clear()
            cls._apply_calls.clear()
            for owner in ("global", "merchant.rules@example.com"):
                shutil.rmtree(
                    project_root / "json" / owner / "Widgets" / "MerchantRules" / "Profiles",
                    ignore_errors=True,
                )

        @staticmethod
        def _copy(value):
            return json.loads(json.dumps(value))

        @staticmethod
        def _segments(path: str) -> list[str]:
            return [segment for segment in str(path or "").strip().strip("/").split("/") if segment]

        def _storage_key(self):
            return self.name if self.scope == "account" else (self.scope, self.name)

        def _root(self):
            return self._documents.get(self._storage_key())

        def _lookup(self, path: str):
            current = self._root()
            for segment in self._segments(path):
                if not isinstance(current, dict) or segment not in current:
                    return None, False
                current = current[segment]
            return current, current is not None or self._storage_key() in self._documents

        def get_json(self, path: str = "", default=None):
            value, found = self._lookup(path)
            return self._copy(value) if found else default

        def set_json(self, path: str, value) -> None:
            segments = self._segments(path)
            if not segments:
                self._documents[self._storage_key()] = self._copy(value)
                return
            root = self._root()
            if not isinstance(root, dict):
                root = {}
                self._documents[self._storage_key()] = root
            current = root
            for segment in segments[:-1]:
                child = current.get(segment)
                if not isinstance(child, dict):
                    child = {}
                    current[segment] = child
                current = child
            current[segments[-1]] = self._copy(value)

        def get(self, path: str, default=None):
            return self.get_json(path, default)

        def set(self, path: str, value) -> None:
            self.set_json(path, value)

        def get_str(self, path: str, default: str = "") -> str:
            return str(self.get_json(path, default))

        def set_str(self, path: str, value: str) -> None:
            self.set_json(path, str(value))

        def get_int(self, path: str, default: int = 0) -> int:
            return int(self.get_json(path, default))

        def set_int(self, path: str, value: int) -> None:
            self.set_json(path, int(value))

        def get_bool(self, path: str, default: bool = False) -> bool:
            return bool(self.get_json(path, default))

        def set_bool(self, path: str, value: bool) -> None:
            self.set_json(path, bool(value))

        def has(self, path: str) -> bool:
            _value, found = self._lookup(path)
            return found

        def keys(self, path: str = "") -> list[str]:
            value = self.get_json(path, {})
            return list(value) if isinstance(value, dict) else []

        def delete(self, path: str) -> bool:
            segments = self._segments(path)
            if not segments:
                return self._documents.pop(self._storage_key(), None) is not None
            root = self._root()
            if not isinstance(root, dict):
                return False
            current = root
            for segment in segments[:-1]:
                child = current.get(segment)
                if not isinstance(child, dict):
                    return False
                current = child
            return current.pop(segments[-1], None) is not None

        def is_ready(self) -> bool:
            return True

        def save(self) -> bool:
            storage_key = self._storage_key()
            self._save_calls[storage_key] = self._save_calls.get(storage_key, 0) + 1
            self._operation_log.append(("save", self.name))
            if not self._save_results.get(storage_key, self._save_results.get(self.name, True)):
                return False
            if storage_key in self._documents:
                self._persisted_documents[storage_key] = self._copy(self._documents[storage_key])
                if self._is_standalone_profile():
                    physical_path = self._standalone_physical_path()
                    physical_path.parent.mkdir(parents=True, exist_ok=True)
                    physical_path.write_text(
                        json.dumps(self._documents[storage_key], indent=2, sort_keys=True),
                        encoding="utf-8",
                    )
            else:
                self._persisted_documents.pop(storage_key, None)
            return True

        def reload(self) -> bool:
            storage_key = self._storage_key()
            self._operation_log.append(("reload", self.name))
            if storage_key in self._reload_overrides:
                self._documents[storage_key] = self._copy(self._reload_overrides[storage_key])
            elif self.name in self._reload_overrides:
                self._documents[storage_key] = self._copy(self._reload_overrides[self.name])
            elif self._is_standalone_profile():
                physical_path = self._standalone_physical_path()
                if not physical_path.is_file():
                    self._documents.pop(storage_key, None)
                    self._persisted_documents.pop(storage_key, None)
                    return False
                try:
                    raw_text = physical_path.read_text(encoding="utf-8")
                    loaded = json.loads(raw_text)
                except (OSError, ValueError):
                    self._documents.pop(storage_key, None)
                    self._persisted_documents.pop(storage_key, None)
                    return False
                self._documents[storage_key] = self._copy(loaded)
                self._persisted_documents[storage_key] = self._copy(loaded)
            elif storage_key in self._persisted_documents:
                self._documents[storage_key] = self._copy(self._persisted_documents[storage_key])
            else:
                self._documents.pop(storage_key, None)
            return True

        def path(self) -> str:
            owner = "global" if self.scope == "global" else "merchant.rules@example.com"
            return str(project_root / "json" / owner / self.name)

        def resolved_path(self) -> str:
            return self.path()

        def apply_to_account(self, path: str, value, target_email: str) -> bool:
            copied_value = self._copy(value)
            storage_key = (str(target_email), self.name)
            existing = self._account_documents.get(storage_key)
            if not str(path or "").strip() and isinstance(existing, dict) and isinstance(copied_value, dict):
                merged = self._copy(existing)
                merged.update(copied_value)
                copied_value = merged
            self._account_documents[storage_key] = copied_value
            self._apply_calls.append((self.name, str(path), copied_value, str(target_email)))
            return True

