    class DummyFrame:
        _states: dict[str, dict[str, object]] = {}

        def __init__(self, key: _NamedFrameKey):
            self.key = key

        @classmethod
        def reset(cls) -> None:
            cls._states.clear()

        @classmethod
        def configure(
            cls,
            key: _NamedFrameKey,
            *,
            exists=True,
            created=True,
            visible=True,
            coords=(0, 0, 20, 20),
            parent: _NamedFrameKey | None = None,
            widget_id=None,
            on_click=None,
        ) -> None:
            previous = cls._states.get(key.path, {})
            generation = int(previous.get("generation", 0)) + 1
            cls._states[key.path] = {
                "exists": exists,
                "created": created,
                "visible": visible,
                "coords": coords,
                "parent": parent,
                "widget_id": widget_id or f"{key.path}@{generation}",
                "on_click": on_click,
                "clicks": int(previous.get("clicks", 0)),
                "generation": generation,
            }

        @classmethod
        def state(cls, key: _NamedFrameKey) -> dict[str, object]:
            return cls._states.setdefault(
                key.path,
                {
                    "exists": False,
                    "created": False,
                    "visible": False,
                    "coords": (0, 0, 0, 0),
                    "parent": None,
                    "widget_id": "",
                    "on_click": None,
                    "clicks": 0,
                    "generation": 0,
                },
            )

        @property
        def exists(self) -> bool:
            value = self.state(self.key)["exists"]
            return bool(value() if callable(value) else value)

        @property
        def is_created(self) -> bool:
            value = self.state(self.key)["created"]
            return bool(value() if callable(value) else value)

        @property
        def is_visible(self) -> bool:
            value = self.state(self.key)["visible"]
            return bool(value() if callable(value) else value)

        @property
        def is_usable(self) -> bool:
            return self.exists and self.is_created and self.is_visible

        @property
        def widget_id(self) -> str:
            value = self.state(self.key)["widget_id"]
            return str(value() if callable(value) else value)

        @property
        def parent_id(self) -> int:
            return 1 if self.state(self.key)["parent"] is not None else 0

        def parent(self):
            parent_key = self.state(self.key)["parent"]
            if parent_key is None:
                raise RuntimeError("root frame has no parent")
            return DummyFrame(parent_key)

        def coords(self) -> tuple[int, int, int, int]:
            value = self.state(self.key)["coords"]
            return tuple(value() if callable(value) else value)

        def click(self) -> None:
            state = self.state(self.key)
            if not self.is_usable:
                return
            state["clicks"] = int(state["clicks"]) + 1
            on_click = state.get("on_click")
            if callable(on_click):
                on_click()

        def mouse_action(self, *_args, **_kwargs) -> None:
            pass

