def _load_merchant_rules_module(project_root: Path):
    _install_stub_modules(project_root)
    module_name = "merchant_rules_regression_target"
    spec = importlib.util.spec_from_file_location(module_name, MERCHANT_RULES_PATH)
    _expect(spec is not None and spec.loader is not None, "Failed to create import spec for MerchantRules.")
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    spec.loader.exec_module(module)
    module.PROFILE_BACKEND = sys.modules["Sources.icefox.MerchantRules.profiles"]
    return module


class _DynamicTestLiveConfigDoc:
    """Legacy test adapter; production persistence tests opt into DummyJsonFactory explicitly."""

    def __init__(self, module, widget):
        self._module = module
        self._widget = widget
        self._memory = getattr(widget, "_test_live_config_memory", None)

    def _path(self) -> Path | None:
        raw_path = str(self._widget.config_path or "").strip()
        return Path(raw_path) if raw_path else None

    def get_json(self, path: str = "", default=None):
        _expect(not str(path or "").strip(), "Dynamic live-config adapter only supports the document root.")
        config_path = self._path()
        if config_path is None or not config_path.exists():
            return self._memory if self._memory is not None else default
        return json.loads(config_path.read_text(encoding="utf-8"))

    def set_json(self, path: str, value) -> None:
        _expect(not str(path or "").strip(), "Dynamic live-config adapter only supports the document root.")
        copied = json.loads(json.dumps(value))
        self._widget._test_live_config_memory = copied
        self._memory = copied
        config_path = self._path()
        if config_path is not None:
            config_path.parent.mkdir(parents=True, exist_ok=True)
            config_path.write_text(json.dumps(copied, indent=2), encoding="utf-8")

    def keys(self, path: str = "") -> list[str]:
        value = self.get_json(path, {})
        return list(value) if isinstance(value, dict) else []

    def has(self, path: str) -> bool:
        if str(path or "").strip():
            return False
        return self.get_json("", None) is not None

    def is_ready(self) -> bool:
        return True

    def save(self) -> bool:
        return True

    def reload(self) -> bool:
        return True

    def path(self) -> str:
        config_path = self._path()
        return str(config_path) if config_path is not None else ""

    def resolved_path(self) -> str:
        return self.path() or self._module.LIVE_CONFIG_DOC_NAME

    def apply_to_account(self, path: str, value, target_email: str) -> bool:
        return self._module.JsonFactory(self._module.LIVE_CONFIG_DOC_NAME).apply_to_account(
            path,
            value,
            target_email,
        )


