def _test_salvage_legacy_suffix_rejects_without_fallback(module) -> None:
    widget = _make_widget(module)
    legacy_values = (
        "suffix",
        "salvage suffix",
        "  SUFFIX  ",
        "  SaLvAgE SuFfIx  ",
    )
    for raw_value in legacy_values:
        _expect_raises(
            ValueError,
            lambda raw_value=raw_value: module._normalize_salvage_rule_mode(raw_value),
            f"Legacy persisted Salvage value {raw_value!r} must be rejected.",
        )
        payload = _minimal_profile_payload(module)
        payload["salvage_settings"] = {
            "rules": [{"enabled": True, "salvage_option": raw_value}],
        }
        _expect_raises(
            ValueError,
            lambda payload=payload: widget._normalize_profile_payload(payload),
            f"Legacy persisted Salvage value {raw_value!r} must fail profile normalization.",
        )

    _expect(
        module._normalize_salvage_operation(module.SALVAGE_OPTION_SUFFIX)
        == module.SALVAGE_OPTION_SUFFIX,
        "Internal suffix extraction operation must remain available to Specific upgrade logic.",
    )
    _expect(
        module._get_salvage_option_label(module.SALVAGE_OPTION_SUFFIX) == "Salvage suffix",
        "Internal suffix extraction labels must remain available for runtime/plan output.",
    )
    invalid_rule = module.SalvageRule(
        enabled=True,
        model_ids=[111],
        salvage_option=module.SALVAGE_OPTION_SUFFIX,
    )
    _expect_raises(
        ValueError,
        lambda: module._normalize_salvage_rule(invalid_rule),
        "A legacy suffix rule must not normalize into a current SalvageRule.",
    )
    _expect_raises(
        ValueError,
        lambda: module._serialize_salvage_rule(invalid_rule),
        "A legacy suffix rule must not serialize as a supported current rule.",
    )

    _expect_raises(
        ValueError,
        lambda: widget._collect_salvage_candidates(
            [],
            [],
            manual_salvage_rule=invalid_rule,
        ),
        "An invalid legacy suffix rule must fail before Salvage planning creates candidates.",
    )


