def _test_manual_vendor_profile_defaults_and_roundtrip(module, temp_root: Path) -> None:
    setting_names = [
        "auto_sell_on_manual_vendor_interaction",
        "auto_buy_on_manual_vendor_interaction",
        "auto_sell_to_any_merchant",
        "auto_sell_any_merchant_normal_items",
        "auto_sell_any_merchant_materials",
        "auto_sell_any_merchant_runes",
    ]

    widget = _make_widget(module)
    normalized = widget._normalize_profile_payload({"version": module.PROFILE_VERSION - 1})
    for setting_name in setting_names:
        _expect(not normalized[setting_name], f"{setting_name} should default off for legacy profiles.")
        _expect(not getattr(widget, setting_name), f"{setting_name} should default off on new widgets.")
    _expect(
        all(normalized["manual_vendor_auto_buy_categories"].values()),
        "Legacy profiles should keep every supported automatic Buy category enabled.",
    )
    _expect(
        all(normalized["manual_vendor_auto_sell_categories"].values()),
        "Legacy profiles should keep every supported automatic Sell category enabled.",
    )
    _expect(
        all(widget.manual_vendor_auto_buy_categories.values()),
        "New widgets should prepare every supported automatic Buy category as enabled.",
    )
    _expect(
        all(widget.manual_vendor_auto_sell_categories.values()),
        "New widgets should prepare every supported automatic Sell category as enabled.",
    )

    config_path = temp_root / "manual_vendor_settings_profile.json"
    widget.config_path = str(config_path)
    for setting_name in setting_names:
        setattr(widget, setting_name, True)
    widget.manual_vendor_auto_buy_categories[module.BUY_KIND_MATERIAL_TARGET] = False
    widget.manual_vendor_auto_sell_categories[module.SELL_KIND_WEAPONS] = False

    _expect(widget._save_profile(), "Manual vendor settings profile should save.")
    saved_payload = json.loads(config_path.read_text(encoding="utf-8"))
    for setting_name in setting_names:
        _expect(saved_payload[setting_name] is True, f"{setting_name} should save as enabled.")
    _expect(
        saved_payload["manual_vendor_auto_buy_categories"][module.BUY_KIND_MATERIAL_TARGET] is False,
        "Automatic Buy category choices should persist in profiles.",
    )
    _expect(
        saved_payload["manual_vendor_auto_sell_categories"][module.SELL_KIND_WEAPONS] is False,
        "Automatic Sell category choices should persist in profiles.",
    )

    reloaded_widget = _make_widget(module)
    reloaded_widget.config_path = str(config_path)
    reloaded_widget._load_profile()
    for setting_name in setting_names:
        _expect(getattr(reloaded_widget, setting_name) is True, f"{setting_name} should reload as enabled.")
    _expect(
        not reloaded_widget.manual_vendor_auto_buy_categories[module.BUY_KIND_MATERIAL_TARGET],
        "Automatic Buy category choices should reload from profiles.",
    )
    _expect(
        not reloaded_widget.manual_vendor_auto_sell_categories[module.SELL_KIND_WEAPONS],
        "Automatic Sell category choices should reload from profiles.",
    )


