def _test_manual_vendor_auto_buy_uses_current_offers(module) -> None:
    widget = _make_widget(module)
    widget.auto_buy_on_manual_vendor_interaction = True
    widget.preview_ready = True
    context = module.ManualVendorContext(
        signature="normal-merchant",
        merchant_types={module.MERCHANT_TYPE_MERCHANT},
        merchant_item_ids=[501],
    )
    plan = module.PlanResult(
        supported_map=True,
        merchant_stock_buys=[
            module.PlannedMerchantBuy(
                model_id=555,
                quantity=2,
                label="Identification Kit",
                check_xunlai_first=True,
            ),
        ],
        has_actions=True,
    )
    captured_buys: list[tuple[int, int, list[int]]] = []
    build_kwargs: list[dict[str, object]] = []

    def _capture_buy(model_id, quantity, *, offered_items=None, cleanup=None):
        captured_buys.append((int(model_id), int(quantity), list(offered_items or [])))
        if False:
            yield None
        return True

    widget._is_merchant_window_open = lambda: True
    widget._get_current_manual_vendor_context = lambda: context
    widget._build_plan = lambda **kwargs: build_kwargs.append(dict(kwargs)) or plan
    widget._ensure_storage_open = lambda **_kwargs: (_ for _ in ()).throw(
        AssertionError("Manual merchant auto-buy must not open Xunlai for Check Xunlai first.")
    )
    widget._buy_merchant_model = _capture_buy

    _drain_generator_return(widget._run_manual_vendor_pass(context))

    _expect(captured_buys == [(555, 2, [501])], "Manual auto-buy should use only the currently opened merchant's offers.")
    _expect(
        len(build_kwargs) == 1 and build_kwargs[0].get("bypass_xunlai_first") is True,
        "Manual merchant auto-buy should bypass only the Xunlai-first phase while retaining the target purchase.",
    )
    _expect(not widget.preview_ready, "Successful manual vendor buys should mark Preview dirty.")


def _test_manual_vendor_category_filters_only_automatic_actions(module) -> None:
    widget = _make_widget(module)
    material_model_id = 921
    widget.catalog_by_model_id[material_model_id] = {
        "model_id": material_model_id,
        "name": "Bone",
        "material_type": "common",
    }
    widget.buy_rules = [
        module._normalize_buy_rule(
            module.BuyRule(
                enabled=True,
                kind=module.BUY_KIND_MERCHANT_STOCK,
                merchant_stock_targets=[
                    module.MerchantStockTarget(model_id=555, target_count=2, max_per_run=0),
                ],
            )
        ),
        module._normalize_buy_rule(
            module.BuyRule(
                enabled=True,
                kind=module.BUY_KIND_MATERIAL_TARGET,
                material_targets=[
                    module.MaterialTarget(model_id=material_model_id, target_count=10, max_per_run=0),
                ],
            )
        ),
    ]
    widget.sell_rules = [
        module._normalize_sell_rule(
            module.SellRule(
                enabled=True,
                kind=module.SELL_KIND_EXPLICIT_MODELS,
                whitelist_targets=[module.WhitelistTarget(model_id=201, keep_count=0)],
            )
        ),
        module._normalize_sell_rule(
            module.SellRule(
                enabled=True,
                kind=module.SELL_KIND_COMMON_MATERIALS,
                whitelist_targets=[module.WhitelistTarget(model_id=material_model_id, keep_count=0)],
            )
        ),
    ]
    widget._get_supported_context = lambda *, passive=False: (
        True,
        "Ready",
        {
            module.MERCHANT_TYPE_MERCHANT: (1.0, 1.0),
            module.MERCHANT_TYPE_MATERIALS: (2.0, 2.0),
            module.MERCHANT_TYPE_RUNE_TRADER: (3.0, 3.0),
            module.MERCHANT_TYPE_SCROLL_TRADER: (4.0, 4.0),
            module.MERCHANT_TYPE_RARE_MATERIALS: (5.0, 5.0),
        },
    )
    widget._collect_inventory_items = lambda: [
        _make_item(
            module,
            item_id=201,
            model_id=201,
            name="Merchant Item",
            rarity="White",
        ),
        _make_item(
            module,
            item_id=202,
            model_id=material_model_id,
            name="Bone",
            quantity=10,
            rarity="White",
            is_material=True,
        ),
    ]

    automatic_plan = widget._build_plan(
        buy_action_rule_kinds={module.BUY_KIND_MERCHANT_STOCK},
        sell_action_rule_kinds={module.SELL_KIND_EXPLICIT_MODELS},
    )
    _expect(
        [buy.model_id for buy in automatic_plan.merchant_stock_buys] == [555],
        "The enabled automatic Buy category should still produce its purchase.",
    )
    _expect(
        not automatic_plan.material_buys,
        "A disabled automatic Buy category should not produce merchant-window purchases.",
    )
    _expect(
        automatic_plan.merchant_sell_item_ids == [201],
        "The enabled automatic Sell category should still produce its sale.",
    )
    _expect(
        not automatic_plan.material_sales,
        "A disabled automatic Sell category should not produce merchant-window sales.",
    )

    normal_plan = widget._build_plan()
    _expect(
        bool(normal_plan.material_buys),
        "Normal Preview Plan should continue using enabled Buy rules from every category.",
    )
    _expect(
        bool(normal_plan.material_sales),
        "Normal Preview Plan should continue using enabled Sell rules from every category.",
    )


