def _test_inventory_shortcut_xunlai_display_cache_reuses_draw_state_and_refreshes_header(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    material_model_id = 921
    material = _make_item(
        module,
        item_id=731,
        model_id=material_model_id,
        name="250 Bones",
        quantity=250,
        is_material=True,
    )
    storage_open = {"value": False}
    bag_quantity = {"value": 250}
    inventory_scan_count = {"value": 0}
    storage_scan_count = {"value": 0}

    def collect_inventory_items():
        inventory_scan_count["value"] += 1
        return [
            _make_item(
                module,
                item_id=material.item_id,
                model_id=material_model_id,
                name="Bones",
                quantity=bag_quantity["value"],
                is_material=True,
            )
        ]

    def collect_storage_items():
        storage_scan_count["value"] += 1
        return [
            _make_item(
                module,
                item_id=732,
                model_id=material_model_id,
                name="Bones",
                quantity=17,
                is_material=True,
            )
        ]

    widget._is_storage_open = lambda: bool(storage_open["value"])
    widget._collect_inventory_items = collect_inventory_items
    widget._collect_storage_items = collect_storage_items
    widget._get_inventory_free_slot_count = lambda: 1
    widget.account_key = "display-cache-account"
    widget.config_path = "display-cache-profile.json"
    widget.map_snapshot = 42

    header_base = widget._format_inventory_shortcut_menu_header_base(material)
    _expect(header_base == "250 Bones - Bags: 250", "Popup header base should capture Bags once when the popup opens.")
    _expect(inventory_scan_count["value"] == 1, "Building the popup header base should capture one inventory snapshot.")

    closed_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    closed_state = widget.inventory_shortcuts_xunlai_display_state
    repeated_closed_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(closed_header == "250 Bones - Bags: 250, Xunlai panes: unavailable", "Closed Xunlai should remain unavailable.")
    _expect(repeated_closed_header == closed_header, "Repeated closed-Xunlai popup draws should reuse display state.")
    _expect(
        widget.inventory_shortcuts_xunlai_display_state is closed_state,
        "Repeated closed-Xunlai popup draws should reuse the same cached state object.",
    )
    _expect(storage_scan_count["value"] == 0, "Closed-Xunlai popup draws must not scan Vault panes.")
    _expect(inventory_scan_count["value"] == 1, "Closed-Xunlai popup draws must not rebuild the Bags snapshot.")

    storage_open["value"] = True
    opened_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    opened_state = widget.inventory_shortcuts_xunlai_display_state
    scans_after_open = (inventory_scan_count["value"], storage_scan_count["value"])
    repeated_opened_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(opened_header == "250 Bones - Bags: 250, Xunlai panes: 17", "Opening Xunlai should refresh the cached Vault header.")
    _expect(repeated_opened_header == opened_header, "Repeated open-Xunlai popup draws should reuse the refreshed header.")
    _expect(opened_state is not closed_state, "The closed-to-open transition should rebuild Xunlai display state once.")
    _expect(
        (inventory_scan_count["value"], storage_scan_count["value"]) == scans_after_open,
        "Idle open-Xunlai popup draws must not repeat inventory snapshots or Vault scans.",
    )

    widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 234})
    positive_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(
        positive_header == "250 Bones - Bags: 250, Xunlai panes: 17, Material Storage: 234 last seen",
        "A positive Material Storage refresh should update the same-popup header.",
    )
    widget._store_inventory_shortcut_material_storage_count_cache({})
    zero_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(
        zero_header == "250 Bones - Bags: 250, Xunlai panes: 17, Material Storage: 0 last seen",
        "A successful zero Material Storage refresh should remain distinct from unavailable state.",
    )
    widget._clear_inventory_shortcut_material_storage_count_cache("regression invalidation")
    unavailable_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(
        unavailable_header == opened_header,
        "Invalidating the Material Storage count should remove only that header segment.",
    )
    _expect(
        (inventory_scan_count["value"], storage_scan_count["value"]) == scans_after_open,
        "Material Storage header updates must not rebuild inventory or Vault display state.",
    )

    bag_quantity["value"] = 1
    bags_stay_captured_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(
        "Bags: 250" in bags_stay_captured_header,
        "Bags should remain the popup-open snapshot while cached header segments update.",
    )
    _expect(
        inventory_scan_count["value"] == scans_after_open[0],
        "Changing live Bags data must not trigger a draw-time Bags refresh.",
    )

    storage_open["value"] = False
    closed_again_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    closed_again_state = widget.inventory_shortcuts_xunlai_display_state
    _expect(
        closed_again_header == "250 Bones - Bags: 250, Xunlai panes: unavailable",
        "Closing Xunlai should invalidate its cached header state without refreshing Bags.",
    )
    storage_open["value"] = True
    reopened_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    reopened_state = widget.inventory_shortcuts_xunlai_display_state
    scans_after_reopen = (inventory_scan_count["value"], storage_scan_count["value"])
    repeated_reopened_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(material, header_base)
    _expect(reopened_header == "250 Bones - Bags: 250, Xunlai panes: 17", "Reopening Xunlai should refresh Vault state again.")
    _expect(closed_again_state is not opened_state, "Closing Xunlai should replace the open cached state.")
    _expect(reopened_state is not closed_again_state, "Reopening Xunlai should replace the closed cached state.")
    _expect(repeated_reopened_header == reopened_header, "The reopened Xunlai state should be reused on later draws.")
    _expect(
        (inventory_scan_count["value"], storage_scan_count["value"]) == scans_after_reopen,
        "Idle draws after reopening Xunlai must not repeat inventory snapshots or Vault scans.",
    )


def _test_inventory_shortcut_xunlai_display_cache_context_and_popup_lifecycle(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    shield_model_id = 930010
    first_shield = _make_item(
        module,
        item_id=741,
        model_id=shield_model_id,
        name="Testing Shield",
        quantity=1,
        is_weapon_like=True,
        item_type_id=int(module.ItemType.Shield),
        item_type_name="Shield",
    )
    second_shield = replace(first_shield, item_id=742)
    inventory_scan_count = {"value": 0}
    storage_scan_count = {"value": 0}

    def collect_inventory_items():
        inventory_scan_count["value"] += 1
        return [first_shield]

    def collect_storage_items():
        storage_scan_count["value"] += 1
        return [replace(first_shield, item_id=743, quantity=3)]

    widget._is_storage_open = lambda: True
    widget._collect_inventory_items = collect_inventory_items
    widget._collect_storage_items = collect_storage_items
    widget.account_key = "context-account-a"
    widget.config_path = "context-profile-a.json"
    widget.map_snapshot = 10

    first_base = widget._format_inventory_shortcut_menu_header_base(first_shield)
    first_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(first_shield, first_base)
    first_state = widget.inventory_shortcuts_xunlai_display_state
    repeated_header = widget._format_inventory_shortcut_menu_header_from_cached_display_state(first_shield, first_base)
    _expect(first_header == "Testing Shield - Bags: 1, Xunlai panes: 3", "Non-withdraw candidates should show cached Vault totals.")
    _expect(repeated_header == first_header, "Non-withdraw candidate Vault headers should be stable across repeated draws.")
    _expect(storage_scan_count["value"] == 1, "A non-withdraw candidate should scan Vault only once per cached state.")
    _expect(inventory_scan_count["value"] == 1, "A non-withdraw candidate should capture Bags only at popup open.")

    second_base = widget._format_inventory_shortcut_menu_header_base(second_shield)
    widget._format_inventory_shortcut_menu_header_from_cached_display_state(second_shield, second_base)
    _expect(widget.inventory_shortcuts_xunlai_display_state is not first_state, "Changing the selected item should rebuild display state.")
    _expect(storage_scan_count["value"] == 2, "Changing the selected item should refresh its Vault quantity once.")

    context_changes = (
        ("account", lambda: setattr(widget, "account_key", "context-account-b")),
        ("profile", lambda: setattr(widget, "config_path", "context-profile-b.json")),
        ("map", lambda: setattr(widget, "map_snapshot", 11)),
    )
    for label, apply_change in context_changes:
        scans_before = storage_scan_count["value"]
        state_before = widget.inventory_shortcuts_xunlai_display_state
        apply_change()
        widget._format_inventory_shortcut_menu_header_from_cached_display_state(second_shield, second_base)
        _expect(
            widget.inventory_shortcuts_xunlai_display_state is not state_before,
            f"A {label} change should invalidate Xunlai display state.",
        )
        _expect(
            storage_scan_count["value"] == scans_before + 1,
            f"A {label} change should refresh the Vault quantity exactly once.",
        )

    widget.inventory_shortcuts_popup_visible = True
    widget.inventory_shortcuts_selected_item = second_shield
    widget.inventory_shortcuts_selected_header = second_base
    widget._close_inventory_shortcuts_popup()
    _expect(widget.inventory_shortcuts_xunlai_display_state is None, "Closing the popup should clear Xunlai display state.")
    _expect(widget.inventory_shortcuts_selected_item is None, "Closing the popup should clear the selected item.")
    _expect(widget.inventory_shortcuts_selected_header == "", "Closing the popup should clear its captured header base.")

    lifecycle_methods = (
        "_handle_inventory_shortcut_right_click",
        "_close_inventory_shortcuts_popup",
        "_draw_inventory_shortcuts_menu",
        "on_enable",
        "_reset_runtime_after_profile_load",
        "_ensure_initialized",
    )
    for method_name in lifecycle_methods:
        method_names = set(getattr(module.MerchantRulesWidget, method_name).__code__.co_names)
        _expect(
            "_clear_inventory_shortcut_xunlai_display_cache" in method_names,
            f"{method_name} should invalidate popup Xunlai display state for its lifecycle transition.",
        )


def _test_inventory_shortcut_display_cache_stays_display_only(module) -> None:
    compositor_names = set(
        module.MerchantRulesWidget._format_inventory_shortcut_menu_header_from_cached_display_state.__code__.co_names
    )
    _expect(
        "_get_cached_inventory_shortcut_header_vault_state" in compositor_names,
        "Popup header composition should use cached Vault display state.",
    )
    _expect(
        "_get_inventory_shortcut_material_storage_quantity" in compositor_names,
        "Popup header composition should use the primitive Material Storage count cache.",
    )
    _expect(
        "_get_inventory_shortcut_bag_quantity" not in compositor_names,
        "Normal popup header draws must not rebuild the Bags inventory snapshot.",
    )
    _expect(
        "_get_inventory_shortcut_vault_quantity" not in compositor_names,
        "Normal popup header draws must not bypass the cached Vault state.",
    )

    popup_draw_names = set(module.MerchantRulesWidget._draw_inventory_shortcuts_menu.__code__.co_names)
    _expect(
        "_format_inventory_shortcut_menu_header_from_cached_display_state" in popup_draw_names,
        "Popup drawing should compose the header from cached display state.",
    )
    _expect(
        "_format_inventory_shortcut_menu_header" not in popup_draw_names,
        "Popup drawing must not call the full header formatter every frame.",
    )

    withdraw_methods = (
        "_run_inventory_shortcut_live_xunlai_pane_withdraw",
        "_run_inventory_shortcut_live_material_storage_withdraw",
        "_run_inventory_shortcut_live_both_withdraw",
    )
    for method_name in withdraw_methods:
        method_names = set(getattr(module.MerchantRulesWidget, method_name).__code__.co_names)
        _expect(
            "_get_inventory_shortcut_live_item_for_action" in method_names,
            f"{method_name} should revalidate the live clicked item before transfer execution.",
        )
        _expect(
            "_get_cached_inventory_shortcut_xunlai_withdraw_label_state" not in method_names,
            f"{method_name} must not authorize a transfer from cached popup state.",
        )
        _expect(
            "inventory_shortcuts_xunlai_display_state" not in method_names,
            f"{method_name} must not read popup display-cache fields.",
        )

    pane_withdraw_names = set(
        module.MerchantRulesWidget._run_inventory_shortcut_live_xunlai_pane_withdraw.__code__.co_names
    )
    _expect(
        "_get_inventory_shortcut_xunlai_pane_withdraw_sources" in pane_withdraw_names
        and "_get_inventory_shortcut_xunlai_pane_withdraw_capacity" in pane_withdraw_names,
        "Live Xunlai withdrawal should continue rebuilding sources and capacity at execution time.",
    )


def _test_inventory_shortcut_popup_mouse_leave_grace_and_close(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    imgui = module.PyImGui
    original_attrs = {
        "get_window_pos": getattr(imgui, "get_window_pos", None),
        "get_window_size": getattr(imgui, "get_window_size", None),
        "get_io": getattr(imgui, "get_io", None),
    }
    original_exists = {name: hasattr(imgui, name) for name in original_attrs}
    mouse_state = types.SimpleNamespace(mouse_pos_x=110.0, mouse_pos_y=110.0)

    try:
        imgui.get_window_pos = lambda: (100.0, 100.0)
        imgui.get_window_size = lambda: (120.0, 160.0)
        imgui.get_io = lambda: mouse_state

        grace_ms = int(module.INVENTORY_SHORTCUTS_MOUSE_LEAVE_GRACE_MS)
        old_opened_at_ms = int(time.time() * 1000) - grace_ms - 100
        widget.inventory_shortcuts_popup_opened_at_ms = old_opened_at_ms
        widget.inventory_shortcuts_popup_last_hovered_at_ms = 0
        _expect(
            not widget._should_close_inventory_shortcuts_popup_for_mouse_leave(),
            "Shortcut popup should stay open while the mouse is inside its window.",
        )
        _expect(
            widget.inventory_shortcuts_popup_last_hovered_at_ms > 0,
            "Shortcut popup should remember when the mouse was inside.",
        )

        mouse_state.mouse_pos_x = 400.0
        mouse_state.mouse_pos_y = 400.0
        widget.inventory_shortcuts_popup_opened_at_ms = int(time.time() * 1000)
        widget.inventory_shortcuts_popup_last_hovered_at_ms = 0
        _expect(
            not widget._should_close_inventory_shortcuts_popup_for_mouse_leave(),
            "Shortcut popup should allow a short grace period after opening.",
        )

        widget.inventory_shortcuts_popup_opened_at_ms = int(time.time() * 1000) - grace_ms - 100
        widget.inventory_shortcuts_popup_last_hovered_at_ms = 0
        _expect(
            widget._should_close_inventory_shortcuts_popup_for_mouse_leave(),
            "Shortcut popup should close when the mouse never reaches it after the grace period.",
        )

        widget.inventory_shortcuts_popup_opened_at_ms = int(time.time() * 1000) - grace_ms - 100
        widget.inventory_shortcuts_popup_last_hovered_at_ms = int(time.time() * 1000) - grace_ms + 50
        _expect(
            not widget._should_close_inventory_shortcuts_popup_for_mouse_leave(),
            "Shortcut popup should allow a short grace period after leaving the menu.",
        )

        widget.inventory_shortcuts_popup_last_hovered_at_ms = int(time.time() * 1000) - grace_ms - 100
        _expect(
            widget._should_close_inventory_shortcuts_popup_for_mouse_leave(),
            "Shortcut popup should close after the mouse stays away from the menu.",
        )
    finally:
        for name, value in original_attrs.items():
            if original_exists[name]:
                setattr(imgui, name, value)
            elif hasattr(imgui, name):
                delattr(imgui, name)


def _test_inventory_shortcut_live_actions_target_clicked_item(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    item = _make_item(module, item_id=731, model_id=930731, name="Book of Secrets", quantity=2)
    original_coroutines = getattr(module.GLOBAL_CACHE, "Coroutines", None)
    had_coroutines = hasattr(module.GLOBAL_CACHE, "Coroutines")
    try:
        module.GLOBAL_CACHE.Coroutines = []
        widget._pause_inventory_plus = lambda: None
        widget._get_inventory_shortcut_live_item_for_action = lambda item_id, model_id: (item, "")
        widget.cleanup_blacklist_model_ids = [item.model_id]

        queued_transfers = []

        def fake_execute_storage_transfers(transfers, **_kwargs):
            queued_transfers.extend(transfers)
            if False:
                yield None
            return module.ExecutionPhaseOutcome(
                label="Right-click Deposit",
                measure_label="items",
                attempted=2,
                completed=2,
            )

        widget._execute_storage_transfers = fake_execute_storage_transfers
        _expect(
            not widget._handle_inventory_shortcut_live_deposit_click(item),
            "Keep-out deposit should arm confirmation on the first click.",
        )
        _expect(
            widget.inventory_shortcuts_live_confirm_action == module.INVENTORY_SHORTCUT_LIVE_ACTION_DEPOSIT,
            "Keep-out deposit should remember the pending deposit confirmation action.",
        )
        _expect(
            widget.inventory_shortcuts_live_confirm_model_id == item.model_id,
            "Live action confirmation should remember the clicked model id.",
        )
        _expect(
            not module.GLOBAL_CACHE.Coroutines,
            "Keep-out deposit first click should not queue a live action.",
        )
        widget._close_inventory_shortcuts_popup()
        _expect(
            widget._inventory_shortcut_live_confirmation_matches(
                module.INVENTORY_SHORTCUT_LIVE_ACTION_DEPOSIT,
                item,
            ),
            "Live action confirmation should survive a passive popup close for the same item.",
        )
        _expect(
            widget._handle_inventory_shortcut_live_deposit_click(item),
            "Keep-out deposit second click should queue the exact clicked item.",
        )
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(len(queued_transfers) == 1, "Right-click deposit should create exactly one transfer.")
        transfer = queued_transfers[0]
        _expect(transfer.item_id == item.item_id, "Right-click deposit should use the clicked item id.")
        _expect(transfer.model_id == item.model_id, "Right-click deposit should keep the clicked model id.")
        _expect(transfer.quantity == item.quantity, "Right-click deposit should use the clicked stack quantity.")
        _expect(
            transfer.direction == module.STORAGE_TRANSFER_DEPOSIT,
            "Right-click deposit should only create a deposit transfer.",
        )

        queued_destroy_actions = []

        def fake_execute_destroy_phase(actions):
            queued_destroy_actions.extend(actions)
            if False:
                yield None
            return module.ExecutionPhaseOutcome(
                label="Destroy",
                measure_label="items",
                attempted=1,
                completed=1,
            )

        widget._execute_destroy_phase = fake_execute_destroy_phase
        widget._clear_inventory_shortcut_live_confirmation()
        _expect(
            not widget._handle_inventory_shortcut_live_destroy_click(item),
            "Destroy should arm confirmation on the first click.",
        )
        _expect(
            not module.GLOBAL_CACHE.Coroutines,
            "Destroy first click should not queue a live action.",
        )
        _expect(
            widget._handle_inventory_shortcut_live_destroy_click(item),
            "Destroy second click should queue the exact clicked item.",
        )
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(len(queued_destroy_actions) == 1, "Right-click destroy should create exactly one action.")
        destroy_action = queued_destroy_actions[0]
        _expect(destroy_action.item_id == item.item_id, "Right-click destroy should use the clicked item id.")
        _expect(
            destroy_action.quantity_to_destroy == item.quantity,
            "Right-click destroy should use the clicked stack quantity.",
        )

        protected_item = _make_item(module, item_id=732, model_id=930732, name="Protected Sword")
        widget._clear_inventory_shortcut_live_confirmation()
        widget.protected_item_model_ids = [protected_item.model_id]
        _expect(
            not widget._handle_inventory_shortcut_live_destroy_click(protected_item),
            "Protected destroy should also require a first confirmation click.",
        )
        _expect(
            "Confirm Destroy Protected Item" in widget.status_message,
            "Protected destroy confirmation should use the stronger protected warning label.",
        )

        salvage_kit_model_id = int(module.ModelID.Salvage_Kit.value)
        salvage_kit = _make_item(
            module,
            item_id=733,
            model_id=salvage_kit_model_id,
            name="Salvage Kit",
        )
        widget._clear_inventory_shortcut_live_confirmation()
        widget.inventory_right_click_live_actions_enabled = True
        widget._inventory_shortcut_runtime_block_reason = lambda: ""
        widget._has_enabled_salvage_settings = lambda: True
        widget._validate_inventory_shortcut_salvage_kit = lambda kit_id, _kit_model_id, option=None: (kit_id, "")
        captured_salvage_passes = []

        def fake_run_salvage_pass(**kwargs):
            captured_salvage_passes.append(dict(kwargs))
            if False:
                yield None

        widget._run_salvage_pass = fake_run_salvage_pass
        _expect(
            not widget._handle_inventory_shortcut_kit_salvage_click(salvage_kit, "gold"),
            "Right-click salvage first click should arm confirmation.",
        )
        _expect(
            widget._inventory_shortcut_live_confirmation_matches(
                widget._get_inventory_shortcut_salvage_action_key("gold"),
                salvage_kit,
            ),
            "Right-click salvage should remember the pending kit/action confirmation.",
        )
        widget._close_inventory_shortcuts_popup()
        _expect(
            widget._inventory_shortcut_live_confirmation_matches(
                widget._get_inventory_shortcut_salvage_action_key("gold"),
                salvage_kit,
            ),
            "Right-click salvage confirmation should survive a passive popup close/reopen.",
        )
        _expect(
            widget._handle_inventory_shortcut_kit_salvage_click(salvage_kit, "gold"),
            "Right-click salvage second click should queue execution after reopening the menu.",
        )
        _expect(len(module.GLOBAL_CACHE.Coroutines) == 1, "Right-click salvage should queue exactly one pass.")
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(len(captured_salvage_passes) == 1, "Right-click salvage should reach the salvage pass.")
        salvage_kwargs = captured_salvage_passes[0]
        _expect(
            salvage_kwargs.get("explicit_salvage_request") is True,
            "Right-click salvage should execute as an explicit salvage request.",
        )
        _expect(
            salvage_kwargs.get("preferred_salvage_kit_id") == salvage_kit.item_id,
            "Right-click salvage should keep targeting the clicked kit.",
        )
        _expect(
            salvage_kwargs.get("rarity_keys") == {"gold"},
            "Right-click salvage should preserve the selected rarity filter.",
        )
    finally:
        if had_coroutines:
            module.GLOBAL_CACHE.Coroutines = original_coroutines
        elif hasattr(module.GLOBAL_CACHE, "Coroutines"):
            delattr(module.GLOBAL_CACHE, "Coroutines")


def _test_inventory_shortcut_deposit_all_matching_split_material_stacks(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    model_id = int(module.ECTOPLASM_MODEL_ID)
    clicked = _make_item(
        module,
        item_id=741,
        model_id=model_id,
        name="Glob of Ectoplasm",
        quantity=250,
        is_rare_material=True,
        is_stackable=True,
    )
    matching_stack = _make_item(
        module,
        item_id=742,
        model_id=model_id,
        name="Glob of Ectoplasm",
        quantity=250,
        is_rare_material=True,
        is_stackable=True,
    )
    matching_remainder = _make_item(
        module,
        item_id=743,
        model_id=model_id,
        name="Glob of Ectoplasm",
        quantity=1,
        is_rare_material=True,
        is_stackable=True,
    )
    other_model = _make_item(
        module,
        item_id=744,
        model_id=921,
        name="Bone",
        quantity=12,
        is_material=True,
        is_stackable=True,
    )
    wrong_same_model_gate = _make_item(
        module,
        item_id=745,
        model_id=model_id,
        name="Ectoplasm Sword",
        quantity=1,
        is_weapon_like=True,
        is_stackable=True,
        item_type_id=int(module.ItemType.Sword),
        item_type_name="Sword",
    )
    protected_source = _make_item(
        module,
        item_id=746,
        model_id=model_id,
        name="Protected Ectoplasm",
        quantity=5,
        is_rare_material=True,
        is_stackable=True,
    )
    keep_out_source = _make_item(
        module,
        item_id=747,
        model_id=model_id,
        name="Keep-Out Ectoplasm",
        quantity=7,
        is_rare_material=True,
        is_stackable=True,
    )
    fresh_sources = [
        clicked,
        matching_stack,
        matching_remainder,
        other_model,
        wrong_same_model_gate,
        protected_source,
        keep_out_source,
    ]

    original_coroutines = getattr(module.GLOBAL_CACHE, "Coroutines", None)
    had_coroutines = hasattr(module.GLOBAL_CACHE, "Coroutines")
    try:
        module.GLOBAL_CACHE.Coroutines = []
        scan_allowed = {"value": False}
        collected_during_run = {"value": 0}
        protected_item_ids = {int(protected_source.item_id)}
        keep_out_item_ids = {int(keep_out_source.item_id)}
        queued_transfers = []
        phase_labels = []
        close_calls = []
        rows = []

        def collect_inventory_items():
            if not scan_allowed["value"]:
                raise AssertionError("Deposit All Matching must not collect source stacks while drawing or queueing.")
            collected_during_run["value"] += 1
            return list(fresh_sources)

        def fake_execute_storage_transfers(transfers, **kwargs):
            queued_transfers.extend(transfers)
            phase_labels.append(kwargs.get("phase_label"))
            completed = sum(max(0, int(transfer.quantity)) for transfer in transfers)
            if False:
                yield None
            return module.ExecutionPhaseOutcome(
                label="Right-click Deposit All Matching",
                measure_label="items",
                attempted=completed,
                completed=completed,
            )

        def click_deposit_all_only(label, _item, action_key, _color=None, enabled=True):
            rows.append((label, action_key, bool(enabled)))
            return bool(action_key == module.INVENTORY_SHORTCUT_LIVE_ACTION_DEPOSIT_ALL_MATCHING and enabled)

        widget._is_storage_open = lambda: False
        widget._collect_storage_items = lambda: (_ for _ in ()).throw(
            AssertionError("Closed Xunlai must not be scanned for Deposit All Matching drawing.")
        )
        widget._collect_material_storage_items = lambda: (_ for _ in ()).throw(
            AssertionError("Deposit All Matching must not scan Material Storage.")
        )
        widget._collect_inventory_items = collect_inventory_items
        widget._get_inventory_shortcut_live_item_for_action = lambda item_id, model_id: (clicked, "")
        widget._inventory_shortcut_runtime_block_reason = lambda: ""
        widget._pause_inventory_plus = lambda: None
        widget._execute_storage_transfers = fake_execute_storage_transfers
        widget._is_inventory_shortcut_protected_item = (
            lambda item: max(0, int(getattr(item, "item_id", 0))) in protected_item_ids
        )
        widget._is_inventory_shortcut_deposit_keep_out = (
            lambda item: max(0, int(getattr(item, "item_id", 0))) in keep_out_item_ids
        )
        widget._draw_inventory_shortcut_live_menu_item = click_deposit_all_only
        widget._close_inventory_shortcuts_popup = lambda **kwargs: close_calls.append(dict(kwargs))

        widget._draw_inventory_shortcut_live_actions(clicked)
        _expect(
            (
                "Deposit All Glob of Ectoplasm",
                module.INVENTORY_SHORTCUT_LIVE_ACTION_DEPOSIT_ALL_MATCHING,
                True,
            )
            in rows,
            "Safe material stack should draw Deposit All with no display count.",
        )
        _expect(
            len(module.GLOBAL_CACHE.Coroutines) == 1,
            "Deposit All Matching click should queue exactly one coroutine.",
        )
        _expect(
            close_calls == [{"clear_confirmation": True}],
            "Deposit All Matching should close the popup after queueing.",
        )
        _expect(
            collected_during_run["value"] == 0,
            "Deposit All Matching must not collect source stacks during popup drawing or queueing.",
        )

        scan_allowed["value"] = True
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(collected_during_run["value"] == 1, "Deposit All Matching should collect fresh sources after the click.")
        _expect(phase_labels == ["Right-click Deposit All Matching"], "Deposit All Matching should use its own transfer phase.")
        _expect(
            [(transfer.item_id, transfer.quantity, transfer.model_id) for transfer in queued_transfers]
            == [
                (clicked.item_id, clicked.quantity, model_id),
                (matching_stack.item_id, matching_stack.quantity, model_id),
                (matching_remainder.item_id, matching_remainder.quantity, model_id),
                (protected_source.item_id, protected_source.quantity, model_id),
                (keep_out_source.item_id, keep_out_source.quantity, model_id),
            ],
            "Deposit All Matching should include protected and keep-out exact-model safe matching material stacks.",
        )
        _expect(
            all(transfer.direction == module.STORAGE_TRANSFER_DEPOSIT for transfer in queued_transfers),
            "Deposit All Matching should build normal deposit transfers.",
        )
    finally:
        if had_coroutines:
            module.GLOBAL_CACHE.Coroutines = original_coroutines
        elif hasattr(module.GLOBAL_CACHE, "Coroutines"):
            delattr(module.GLOBAL_CACHE, "Coroutines")


