def _test_inventory_shortcut_xunlai_pane_withdraw_label_and_guards(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    material_model_id = 921
    material = _make_item(
        module,
        item_id=751,
        model_id=material_model_id,
        name="Bone",
        quantity=15,
        is_material=True,
    )
    same_model_weapon = _make_item(
        module,
        item_id=752,
        model_id=material_model_id,
        name="Bone Sword",
        quantity=1,
        is_weapon_like=True,
        item_type_id=int(module.ItemType.Sword),
        item_type_name="Sword",
    )

    storage_open = {"value": True}
    widget._is_storage_open = lambda: bool(storage_open["value"])
    widget._collect_inventory_items = lambda: [material]
    widget._collect_storage_items = lambda: [
        _make_item(module, item_id=761, model_id=material_model_id, name="Bone", quantity=250, is_material=True),
        _make_item(module, item_id=762, model_id=material_model_id, name="Bone", quantity=100, is_material=True),
        same_model_weapon,
    ]
