def _test_inventory_shortcut_xunlai_pane_withdraw_uses_fresh_sources(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    material_model_id = 921
    material = _make_item(
        module,
        item_id=771,
        model_id=material_model_id,
        name="Bone",
        quantity=250,
        is_material=True,
    )
    storage_sources = [
        _make_item(module, item_id=781, model_id=material_model_id, name="Bone", quantity=250, is_material=True),
    ]
    inventory_items = [material]
    free_slots = {"value": 1}
    queued_transfers = []
    resumed = []

    original_coroutines = getattr(module.GLOBAL_CACHE, "Coroutines", None)
    had_coroutines = hasattr(module.GLOBAL_CACHE, "Coroutines")
    try:
        module.GLOBAL_CACHE.Coroutines = []
        widget._is_storage_open = lambda: True
        widget._collect_inventory_items = lambda: list(inventory_items)
        widget._collect_storage_items = lambda: list(storage_sources)
        widget._get_inventory_free_slot_count = lambda: int(free_slots["value"])
        widget._inventory_shortcut_runtime_block_reason = lambda: ""
        widget._get_inventory_shortcut_live_item_for_action = lambda item_id, model_id: (material, "")
        widget._pause_inventory_plus = lambda: types.SimpleNamespace(resume=lambda: resumed.append(True))
        widget._get_material_storage_quantity_and_slot = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("Pane-only withdraw must not probe Material Storage.")
        )
        widget._collect_material_storage_items = lambda: (_ for _ in ()).throw(
            AssertionError("Pane-only withdraw must not collect Material Storage items.")
        )
        widget._get_storage_model_item_ids_for_crafting = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("Pane-only withdraw must not use mixed crafting storage scans.")
        )

        stale_label, stale_enabled = widget._format_inventory_shortcut_xunlai_withdraw_label(material)
        _expect(stale_enabled, "Initial pane-only withdraw label should be enabled before the source changes.")
        _expect("250 available" in stale_label, "Initial pane-only withdraw label should reflect the first scan.")

        storage_sources[:] = [
            _make_item(module, item_id=782, model_id=material_model_id, name="Bone", quantity=100, is_material=True),
        ]
        inventory_items[:] = [
            _make_item(module, item_id=771, model_id=material_model_id, name="Bone", quantity=200, is_material=True),
        ]
        free_slots["value"] = 0

        def fake_execute_storage_transfers(transfers, **_kwargs):
            queued_transfers.extend(transfers)
            if False:
                yield None
            return module.ExecutionPhaseOutcome(
                label="Right-click Xunlai Withdraw",
                measure_label="items",
                attempted=sum(int(transfer.quantity) for transfer in transfers),
                completed=sum(int(transfer.quantity) for transfer in transfers),
            )

        widget._execute_storage_transfers = fake_execute_storage_transfers
        _expect(
            widget._queue_inventory_shortcut_live_xunlai_pane_withdraw(material),
            "Pane-only withdraw should queue a live action for a readable material.",
        )
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(len(queued_transfers) == 1, "Pane-only withdraw should execute one bounded transfer pass.")
        transfer = queued_transfers[0]
        _expect(transfer.item_id == 782, "Pane-only withdraw should build fresh source item ids at click time.")
        _expect(transfer.quantity == 50, "Pane-only withdraw should recalculate live capacity at click time.")
        _expect(transfer.direction == module.STORAGE_TRANSFER_WITHDRAW, "Pane-only withdraw should only create withdraw transfers.")
        _expect(resumed == [True], "Pane-only withdraw should resume Inventory+ after the live move.")

        queued_transfers.clear()
        widget._is_storage_open = lambda: False
        _drain_generator_return(
            widget._run_inventory_shortcut_live_xunlai_pane_withdraw(
                material.item_id,
                material.model_id,
                material.name,
            )
        )
        _expect(not queued_transfers, "Closed-Xunlai pane-only withdraw should fail before creating transfers.")
        _expect("Open Xunlai" in widget.status_message, "Closed-Xunlai pane-only withdraw should fail closed with a clear status.")
    finally:
        if had_coroutines:
            module.GLOBAL_CACHE.Coroutines = original_coroutines
        elif hasattr(module.GLOBAL_CACHE, "Coroutines"):
            delattr(module.GLOBAL_CACHE, "Coroutines")


