    widget._collect_inventory_items = lambda: [tome_clicked]
    widget._collect_storage_items = lambda: [non_tome_source]
    label, enabled = widget._format_inventory_shortcut_xunlai_withdraw_label(tome_clicked)
    _expect(not enabled, "Tome withdraw should ignore same-model source stacks that do not pass the Tome live gate.")
    _expect(label == "No Warrior Tome in Xunlai Panes", "Tome withdraw should fail closed when sources fail the same gate.")


