def _test_inventory_shortcut_material_storage_count_refresh_cache(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    material_model_id = 921
    other_material_model_id = 925
    material = _make_item(
        module,
        item_id=821,
        model_id=material_model_id,
        name="Bone",
        quantity=20,
        is_material=True,
    )
    material_storage_items = [
        _make_item(module, item_id=831, model_id=material_model_id, name="Bone", quantity=250, is_material=True),
        _make_item(module, item_id=832, model_id=material_model_id, name="Bone", quantity=250, is_material=True),
        _make_item(module, item_id=833, model_id=other_material_model_id, name="Iron Ingot", quantity=75, is_material=True),
        _make_item(
            module,
            item_id=834,
            model_id=material_model_id,
            name="Bone Sword",
            quantity=1,
            is_weapon_like=True,
            item_type_id=int(module.ItemType.Sword),
            item_type_name="Sword",
        ),
    ]
    storage_open = {"value": True}
    material_storage_scan_allowed = {"value": False}
    material_storage_scan_count = {"value": 0}

    def collect_material_storage_items():
        if not material_storage_scan_allowed["value"]:
            raise AssertionError("Material Storage refresh should only collect after the explicit refresh click.")
        material_storage_scan_count["value"] += 1
        return list(material_storage_items)

    original_coroutines = getattr(module.GLOBAL_CACHE, "Coroutines", None)
    had_coroutines = hasattr(module.GLOBAL_CACHE, "Coroutines")
    try:
        module.GLOBAL_CACHE.Coroutines = []
        widget._is_storage_open = lambda: bool(storage_open["value"])
        widget._collect_inventory_items = lambda: [material]
        widget._collect_storage_items = lambda: []
        widget._get_inventory_free_slot_count = lambda: 1
        widget._collect_material_storage_items = collect_material_storage_items
        widget._get_material_storage_quantity_and_slot = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("Material Storage count refresh should not use the quantity/slot helper.")
        )
        widget._get_storage_model_item_ids_for_crafting = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("Material Storage count refresh should not use mixed crafting storage scans.")
        )
        widget._inventory_shortcut_runtime_block_reason = lambda: ""
        widget._get_inventory_shortcut_live_item_for_action = lambda item_id, model_id: (material, "")
        widget.account_key = "test-account"
        widget.config_path = "test-profile.json"
        widget.map_ready_snapshot = True
        widget.map_snapshot = 100
        widget.map_instance_uptime_snapshot_ms = 1000

        label, enabled = widget._format_inventory_shortcut_material_storage_withdraw_label(material)
        _expect(enabled, "Material Storage withdraw should be enabled before an explicit count refresh.")
        _expect(label == "Withdraw Bone From Material Storage", "No cache should keep the Material Storage withdraw label count-free.")
        _expect(material_storage_scan_count["value"] == 0, "Popup label drawing should not collect Material Storage counts.")

        material_storage_scan_allowed["value"] = True
        _expect(
            widget._queue_inventory_shortcut_live_material_storage_count_refresh(material),
            "Material Storage count refresh should queue a live action for a safe material.",
        )
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(material_storage_scan_count["value"] == 1, "Material Storage count refresh should scan only after click.")
        _expect(
            widget.inventory_shortcuts_material_storage_count_cache == {material_model_id: 500, other_material_model_id: 75},
            "Material Storage count refresh should store primitive model-id quantities only.",
        )
        cached_label, cached_enabled = widget._format_inventory_shortcut_material_storage_withdraw_label(material)
        _expect(cached_enabled, "Material Storage withdraw should remain enabled after count refresh.")
        _expect(
            cached_label == "Withdraw Bone From Material Storage (500 last seen)",
            "Material Storage withdraw should show refreshed counts as last-seen display data.",
        )
        cached_header = widget._format_inventory_shortcut_menu_header(material)
        _expect(
            "Material Storage: 500 last seen" in cached_header,
            "Material Storage header should show refreshed counts as last-seen display data.",
        )

        widget.map_instance_uptime_snapshot_ms = 1500
        advancing_uptime_label, advancing_uptime_enabled = widget._format_inventory_shortcut_material_storage_withdraw_label(
            material
        )
        _expect(
            advancing_uptime_enabled,
            "Material Storage withdraw should remain enabled when the same map session uptime advances.",
        )
        _expect(
            advancing_uptime_label == "Withdraw Bone From Material Storage (500 last seen)",
            "Advancing map session uptime should not hide a freshly refreshed Material Storage count.",
        )

        def failing_collect_material_storage_items():
            material_storage_scan_count["value"] += 1
            raise RuntimeError("simulated Material Storage scan failure")

        widget._collect_material_storage_items = failing_collect_material_storage_items
        _expect(
            widget._queue_inventory_shortcut_live_material_storage_count_refresh(material),
            "Material Storage count refresh should still queue when the later scan will fail.",
        )
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(
            not widget.inventory_shortcuts_material_storage_count_cache,
            "Failed Material Storage count refresh should clear the display cache.",
        )
        _expect(
            widget._get_inventory_shortcut_material_storage_quantity(material) is None,
            "Failed Material Storage count refresh should hide stale counts.",
        )

        widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 500})
        storage_open["value"] = False
        _expect(
            widget._get_inventory_shortcut_material_storage_quantity(material) is None,
            "Closed Xunlai should hide Material Storage display counts.",
        )
        _expect(
            widget.inventory_shortcuts_material_storage_count_cache_captured_at_ms == 0,
            "Closed Xunlai should clear the Material Storage display cache.",
        )

        storage_open["value"] = True
        widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 500})
        widget.map_snapshot += 1
        _expect(
            widget._get_inventory_shortcut_material_storage_quantity(material) is None,
            "Map/session context changes should invalidate Material Storage display counts.",
        )

        widget.map_snapshot -= 1
        widget.map_instance_uptime_snapshot_ms = 2000
        widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 500})
        widget.map_instance_uptime_snapshot_ms = 1000
        _expect(
            widget._get_inventory_shortcut_material_storage_quantity(material) is None,
            "Map session uptime reset should invalidate Material Storage display counts.",
        )

        widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 500})
        widget.account_key = "different-account"
        _expect(
            widget._get_inventory_shortcut_material_storage_quantity(material) is None,
            "Account/profile context changes should invalidate Material Storage display counts.",
        )

        widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 500})
        widget._ensure_initialized = lambda: None
        widget._advance_multibox_batch = lambda: None
        widget._update_manual_vendor_runtime = lambda: None
        widget._update_identify_runtime = lambda: None
        widget._update_auto_cleanup_runtime = lambda: None
        widget._update_salvage_runtime = lambda: None
        widget._update_instant_destroy_runtime = lambda: None
        widget._collect_material_storage_items = lambda: (_ for _ in ()).throw(
            AssertionError("_tick_runtime must not collect Material Storage items.")
        )
        widget._get_material_storage_quantity_and_slot = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("_tick_runtime must not probe Material Storage counts.")
        )
        widget._tick_runtime()
        _expect(
            widget.inventory_shortcuts_material_storage_count_cache,
            "_tick_runtime should not clear a cache while storage remains open.",
        )
    finally:
        if had_coroutines:
            module.GLOBAL_CACHE.Coroutines = original_coroutines
        elif hasattr(module.GLOBAL_CACHE, "Coroutines"):
            delattr(module.GLOBAL_CACHE, "Coroutines")


def _test_inventory_shortcut_material_storage_withdraw_uses_fresh_sources(module) -> None:
    widget = _make_inventory_shortcut_test_widget(module)
    material_model_id = 921
    original_material = _make_item(
        module,
        item_id=801,
        model_id=material_model_id,
        name="Bone",
        quantity=250,
        is_material=True,
    )
    live_material = {"item": original_material}
    material_storage_sources = [
        _make_item(module, item_id=811, model_id=material_model_id, name="Bone", quantity=250, is_material=True),
    ]
    inventory_items = [original_material]
    free_slots = {"value": 1}
    storage_open = {"value": True}
    material_storage_scan_allowed = {"value": False}
    material_storage_scan_count = {"value": 0}
    queued_transfers = []
    resumed = []

    def collect_material_storage_items():
        if not material_storage_scan_allowed["value"]:
            raise AssertionError("Material Storage should only be collected after the explicit withdraw click.")
        material_storage_scan_count["value"] += 1
        return list(material_storage_sources)

    original_coroutines = getattr(module.GLOBAL_CACHE, "Coroutines", None)
    had_coroutines = hasattr(module.GLOBAL_CACHE, "Coroutines")
    try:
        module.GLOBAL_CACHE.Coroutines = []
        widget._is_storage_open = lambda: bool(storage_open["value"])
        widget._collect_inventory_items = lambda: list(inventory_items)
        widget._get_inventory_free_slot_count = lambda: int(free_slots["value"])
        widget._collect_material_storage_items = collect_material_storage_items
        widget._get_material_storage_quantity_and_slot = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("Material Storage withdraw should not use the quantity/slot helper.")
        )
        widget._get_storage_model_item_ids_for_crafting = lambda _model_id: (_ for _ in ()).throw(
            AssertionError("Material Storage withdraw should not use mixed crafting storage scans.")
        )
        widget._inventory_shortcut_runtime_block_reason = lambda: ""
        widget._get_inventory_shortcut_live_item_for_action = lambda item_id, model_id: (live_material["item"], "")
        widget._pause_inventory_plus = lambda: types.SimpleNamespace(resume=lambda: resumed.append(True))

        label, enabled = widget._format_inventory_shortcut_material_storage_withdraw_label(original_material)
        _expect(enabled, "Material Storage withdraw label should be enabled before the click.")
        _expect(label == "Withdraw Bone From Material Storage", "Material Storage withdraw label should omit quantities.")
        _expect(material_storage_scan_count["value"] == 0, "Material Storage label drawing should not collect source items.")
        widget._store_inventory_shortcut_material_storage_count_cache({material_model_id: 999})
        cached_label, cached_enabled = widget._format_inventory_shortcut_material_storage_withdraw_label(original_material)
        _expect(cached_enabled, "Material Storage withdraw should stay enabled with a display count cache.")
        _expect(
            cached_label == "Withdraw Bone From Material Storage (999 last seen)",
            "Material Storage withdraw should use cached counts only as display text.",
        )
        _expect(
            material_storage_scan_count["value"] == 0,
            "Cached Material Storage withdraw label should still avoid live Material Storage scans.",
        )

        material_storage_sources[:] = [
            _make_item(module, item_id=812, model_id=material_model_id, name="Bone", quantity=100, is_material=True),
            _make_item(module, item_id=813, model_id=999002, name="Other Material", quantity=250, is_material=True),
            _make_item(
                module,
                item_id=814,
                model_id=material_model_id,
                name="Bone Sword",
                quantity=1,
                is_weapon_like=True,
                item_type_id=int(module.ItemType.Sword),
                item_type_name="Sword",
            ),
        ]
        live_material["item"] = _make_item(
            module,
            item_id=801,
            model_id=material_model_id,
            name="Bone",
            quantity=200,
            is_material=True,
        )
        inventory_items[:] = [live_material["item"]]
        free_slots["value"] = 0
        material_storage_scan_allowed["value"] = True

        def fake_execute_storage_transfers(transfers, **_kwargs):
            queued_transfers.extend(transfers)
            if False:
                yield None
            return module.ExecutionPhaseOutcome(
                label="Right-click Material Storage Withdraw",
                measure_label="items",
                attempted=sum(int(transfer.quantity) for transfer in transfers),
                completed=sum(int(transfer.quantity) for transfer in transfers),
            )

        widget._execute_storage_transfers = fake_execute_storage_transfers
        _expect(
            widget._queue_inventory_shortcut_live_material_storage_withdraw(original_material),
            "Material Storage withdraw should queue a live action for a readable material.",
        )
        _drain_generator_return(module.GLOBAL_CACHE.Coroutines.pop(0))
        _expect(material_storage_scan_count["value"] == 1, "Material Storage source scan should happen once after click.")
        _expect(len(queued_transfers) == 1, "Material Storage withdraw should execute one bounded transfer pass.")
        transfer = queued_transfers[0]
        _expect(transfer.item_id == 812, "Material Storage withdraw should build fresh source item ids at click time.")
        _expect(transfer.quantity == 50, "Material Storage withdraw should recalculate live capacity at click time.")
        _expect(
            transfer.direction == module.STORAGE_TRANSFER_WITHDRAW,
            "Material Storage withdraw should only create withdraw transfers.",
        )
        _expect(resumed == [True], "Material Storage withdraw should resume Inventory+ after the live move.")

        queued_transfers.clear()
        material_storage_scan_allowed["value"] = False
        scan_count_before_no_capacity = material_storage_scan_count["value"]
        inventory_items[:] = [
            _make_item(module, item_id=801, model_id=material_model_id, name="Bone", quantity=250, is_material=True)
        ]
        live_material["item"] = inventory_items[0]
        free_slots["value"] = 0
        _drain_generator_return(
            widget._run_inventory_shortcut_live_material_storage_withdraw(
                original_material.item_id,
                original_material.model_id,
                original_material.name,
            )
        )
        _expect(
            material_storage_scan_count["value"] == scan_count_before_no_capacity,
            "No-capacity Material Storage withdraw should fail before collecting source items.",
        )
        _expect(not queued_transfers, "No-capacity Material Storage withdraw should fail before creating transfers.")
        _expect("Inventory full" in widget.status_message, "No-capacity Material Storage withdraw should fail closed.")

        storage_open["value"] = False
        scan_count_before_closed = material_storage_scan_count["value"]
        _drain_generator_return(
            widget._run_inventory_shortcut_live_material_storage_withdraw(
                original_material.item_id,
                original_material.model_id,
                original_material.name,
            )
        )
        _expect(
            material_storage_scan_count["value"] == scan_count_before_closed,
            "Closed-Xunlai Material Storage withdraw should fail before collecting source items.",
        )
        _expect(
            "Open Xunlai" in widget.status_message,
            "Closed-Xunlai Material Storage withdraw should fail closed with a clear status.",
        )
    finally:
        if had_coroutines:
            module.GLOBAL_CACHE.Coroutines = original_coroutines
        elif hasattr(module.GLOBAL_CACHE, "Coroutines"):
            delattr(module.GLOBAL_CACHE, "Coroutines")


