def _test_stackable_salvage_rule_drains_same_stack(module) -> None:
    widget = _make_widget(module)
    rule = module.SalvageRule(
        enabled=True,
        model_ids=[3100],
        salvage_option=module.SALVAGE_OPTION_MATERIALS,
    )
    quantity_by_item_id = {501: 3}
    calls: list[tuple[int, int, int]] = []

    def _live_item(item_id: int):
        quantity = max(0, int(quantity_by_item_id.get(int(item_id), 0)))
        if int(item_id) != 501 or quantity <= 0:
            return None
        return _make_item(
            module,
            item_id=501,
            model_id=3100,
            name="Stacked Salvage Drop",
            quantity=quantity,
            rarity="White",
            salvageable=True,
            is_stackable=True,
        )

    def _fake_salvage_one(candidate, *_args, **_kwargs):
        calls.append((candidate.item.item_id, candidate.item.model_id, candidate.item.quantity))
        quantity_by_item_id[501] = max(0, int(quantity_by_item_id.get(501, 0)) - 1)
        if quantity_by_item_id[501] <= 0:
            quantity_by_item_id.pop(501, None)
            status = "salvaged_item_gone"
        else:
            status = "salvaged"
        if False:
            yield None
        return status

    widget._build_inventory_item_info = _live_item
    widget._salvage_one_item_with_rule = _fake_salvage_one
    widget._get_salvage_kit_id_for_option = lambda *_args, **_kwargs: 77
    widget._collect_inventory_items = lambda: (_ for _ in ()).throw(
        AssertionError("Stack draining must not start a broad inventory rescan.")
    )

    candidate = module.SalvageCandidate(item=_live_item(501), rule_index=0, rule=rule, reason="selected model")
    outcome = _drain_generator_return(widget._salvage_candidate_with_stack_drain(candidate, []))

    _expect(outcome.completed == 3, "Stackable salvage should continue until the original stack is gone.")
    _expect(outcome.timeout_failures == 0, "The final stack item leaving inventory should not create a no-progress failure.")
    _expect(
        calls == [(501, 3100, 3), (501, 3100, 2), (501, 3100, 1)],
        "Stack drain should reuse the same item id/model.",
    )
    _expect(501 not in quantity_by_item_id, "Stack drain should consume the stubbed stack.")


