def _capture_normal_material_salvage_popup_timeout(
    module,
    *,
    rarity: str,
    is_stackable: bool,
) -> list[int]:
    widget = _make_widget(module)
    rule = module.SalvageRule(
        enabled=True,
        model_ids=[3106],
        salvage_option=module.SALVAGE_OPTION_MATERIALS,
    )
    live_item = _make_item(
        module,
        item_id=506,
        model_id=3106,
        name="Common Salvage Drop",
        quantity=1,
        rarity=rarity,
        salvageable=True,
        is_stackable=bool(is_stackable),
    )
    confirmation_timeouts: list[int] = []

    def _fake_queue_salvage_start(*_args, **_kwargs):
        if False:
            yield None
        return True

    def _fake_wait_and_confirm_materials_popup(*_args, timeout_ms: int = 0, **_kwargs):
        confirmation_timeouts.append(int(timeout_ms))
        if False:
            yield None
        return "handled"

    widget._get_salvage_candidate_block_reason = lambda *_args, **_kwargs: ""
    widget._get_salvage_kit_id_for_option = lambda *_args, **_kwargs: 77
    widget._get_salvage_kit_model_id = lambda _kit_id: int(module.ModelID.Salvage_Kit.value)
    widget._queue_salvage_start = _fake_queue_salvage_start
    widget._wait_and_confirm_materials_popup = _fake_wait_and_confirm_materials_popup
    widget._get_inventory_item_ids = lambda: []
    widget._build_inventory_item_info = lambda item_id: live_item if int(item_id) == 506 else None

    candidate = module.SalvageCandidate(item=live_item, rule_index=0, rule=rule, reason="selected model")
    status = _drain_generator_return(widget._salvage_one_item_with_rule(candidate, []))

    _expect(status == "salvaged_item_gone", "Common material salvage should still wait for confirmed completion.")
    return confirmation_timeouts


