class _FakeNormalMaterialsWarningState:
    def __init__(self, *, item_id: int = 506, model_id: int = 3106):
        self.item_id = int(item_id)
        self.model_id = int(model_id)
        self.quantity = 1
        self.item_present = True
        self.popup_open = False
        self.popup_open_before_start = False
        self.show_popup_on_start = True
        self.complete_without_popup = False
        self.hidden_root = False
        self.hidden_parent = False
        self.zero_size_yes = False
        self.zero_size_no = False
        self.close_on_yes = True
        self.remove_item_on_yes = True
        self.legacy_root_visible = False
        self.legacy_cancel_exists = False
        self.frame_generation = 0
        self.change_on_confirmation_cycle = ""
        self.confirmation_cycle_changed = False
        self.change_on_queue = ""
        self.queue_changed = False
        self.events: list[tuple[object, ...]] = []

    def frame_ids(self) -> tuple[int, int, int, int]:
        base = 900 + (int(self.frame_generation) * 10)
        return base, base + 1, base + 2, base + 3


def _run_normal_materials_warning_case(
    module,
    *,
    rarity: str,
    configure_state=None,
):
    state = _FakeNormalMaterialsWarningState()
    if callable(configure_state):
        configure_state(state)
    state.popup_open = bool(state.popup_open_before_start)

    original_action_queue_manager = module.ActionQueueManager
    original_wait = module.Routines.Yield.wait
    had_global_cache_item = hasattr(module.GLOBAL_CACHE, "Item")
    original_global_cache_item = getattr(module.GLOBAL_CACHE, "Item", None)
    global_cache_item_replaced = not bool(
        original_global_cache_item is not None
        and getattr(original_global_cache_item, "Properties", None) is not None
        and callable(getattr(original_global_cache_item.Properties, "GetQuantity", None))
    )
    if global_cache_item_replaced:
        module.GLOBAL_CACHE.Item = types.SimpleNamespace(
            Properties=types.SimpleNamespace(GetQuantity=lambda _item_id: state.quantity),
        )
    original_get_quantity = module.GLOBAL_CACHE.Item.Properties.GetQuantity

    module.Frame.reset()
    frame_id = module.FrameId
    screen_frame = frame_id.ScreenFrame
    screen_c6 = screen_frame.C6
    warning_root = screen_c6.SalvageMaterialsDialog
    no_button = warning_root.NoButton
    yes_button = warning_root.YesButton

    module.Frame.configure(screen_frame)
    module.Frame.configure(
        screen_c6,
        parent=screen_frame,
        visible=lambda: not state.hidden_parent,
    )
    module.Frame.configure(
        warning_root,
        parent=screen_c6,
        visible=lambda: state.popup_open and not state.hidden_root,
        widget_id=lambda: f"materials-root@{state.frame_generation}",
    )
    module.Frame.configure(
        no_button,
        parent=warning_root,
        coords=lambda: (10, 10, 10, 10) if state.zero_size_no else (10, 10, 110, 30),
        widget_id=lambda: f"materials-no@{state.frame_generation}",
        on_click=lambda: (
            state.events.append(("no", state.frame_ids()[2])),
            setattr(state, "popup_open", False),
        ),
    )

    def _click_yes() -> None:
        state.events.append(("yes", state.frame_ids()[3]))
        if state.close_on_yes:
            state.popup_open = False
        if state.remove_item_on_yes:
            state.item_present = False

    module.Frame.configure(
        yes_button,
        parent=warning_root,
        coords=lambda: (10, 10, 10, 10) if state.zero_size_yes else (10, 10, 110, 30),
        widget_id=lambda: f"materials-yes@{state.frame_generation}",
        on_click=_click_yes,
    )
    deprecated_lesser_root = frame_id.DeprecatedLesserSalvageDialog
    module.Frame.configure(
        deprecated_lesser_root,
        visible=lambda: state.legacy_root_visible,
    )
    module.Frame.configure(
        deprecated_lesser_root.NoButton,
        exists=lambda: state.legacy_cancel_exists,
        created=lambda: state.legacy_cancel_exists,
        visible=lambda: state.legacy_root_visible and state.legacy_cancel_exists,
        parent=deprecated_lesser_root,
        on_click=lambda: (
            state.events.append(("legacy_no",)),
            setattr(state, "legacy_root_visible", False),
        ),
    )

    class ImmediateActionQueue:
        def AddAction(self, queue_name: str, action, *args) -> None:
            state.events.append(("queue", str(queue_name), getattr(action, "__name__", str(action))))
            if state.change_on_queue and not state.queue_changed:
                state.queue_changed = True
                if state.change_on_queue == "frame":
                    state.frame_generation += 1
                elif state.change_on_queue == "item":
                    state.item_present = False
                elif state.change_on_queue == "protection":
                    widget.protected_item_model_ids = [state.model_id]
            action(*args)

        @staticmethod
        def IsEmpty(_queue_name: str) -> bool:
            return True

    action_queue = ImmediateActionQueue()
    widget = _make_widget(module)
    rule = module.SalvageRule(
        enabled=True,
        model_ids=[state.model_id],
        salvage_option=module.SALVAGE_OPTION_MATERIALS,
    )
    widget.salvage_settings = _salvage_settings(module, rules=[rule])
    widget.preview_ready = True

    def _live_item(item_id: int):
        if not state.item_present or int(item_id) != state.item_id:
            return None
        return _make_item(
            module,
            item_id=state.item_id,
            model_id=state.model_id,
            name=f"{rarity} Materials Test",
            quantity=state.quantity,
            rarity=rarity,
            identified=True,
            salvageable=True,
            is_weapon_like=True,
        )

    def _queue_start(item_id: int, kit_id: int, attempt: int):
        state.events.append(("start", int(item_id), int(kit_id), int(attempt)))
        if state.show_popup_on_start:
            state.popup_open = True
        elif state.complete_without_popup:
            state.item_present = False
        if False:
            yield None
        return True

    def _wait(milliseconds: int):
        state.events.append(("wait", int(milliseconds)))
        if (
            int(milliseconds) == 50
            and state.popup_open
            and state.change_on_confirmation_cycle
            and not state.confirmation_cycle_changed
        ):
            state.confirmation_cycle_changed = True
            change_kind = str(state.change_on_confirmation_cycle)
            if change_kind == "frame":
                state.frame_generation += 1
            elif change_kind == "item":
                state.item_present = False
            elif change_kind == "model":
                state.model_id += 1
            elif change_kind == "quantity":
                state.quantity += 1
            elif change_kind == "rule":
                widget.salvage_settings = _salvage_settings(
                    module,
                    rules=[replace(rule, name="Changed Materials Rule")],
                )
            elif change_kind == "protection":
                widget.protected_item_model_ids = [state.model_id]
        yield int(milliseconds)

    widget._get_salvage_kit_id_for_option = lambda *_args, **_kwargs: 77
    widget._get_salvage_kit_model_id = lambda _kit_id: int(module.ModelID.Salvage_Kit.value)
    widget._queue_salvage_start = _queue_start
    widget._get_inventory_item_ids = lambda: [state.item_id] if state.item_present else []
    widget._build_inventory_item_info = _live_item

    module.ActionQueueManager = lambda: action_queue
    module.Routines.Yield.wait = _wait
    module.GLOBAL_CACHE.Item.Properties.GetQuantity = lambda _item_id: state.quantity if state.item_present else 0
    try:
        live_item = _live_item(state.item_id)
        _expect(live_item is not None, "The normal Materials fixture should start with a live item.")
        candidate = module.SalvageCandidate(item=live_item, rule_index=0, rule=rule, reason="selected model")
        status = _drain_generator_return(widget._salvage_one_item_with_rule(candidate, []))
        return status, state, widget
    finally:
        module.Frame.reset()
        module.ActionQueueManager = original_action_queue_manager
        module.Routines.Yield.wait = original_wait
        if global_cache_item_replaced and had_global_cache_item:
            module.GLOBAL_CACHE.Item = original_global_cache_item
        elif global_cache_item_replaced:
            delattr(module.GLOBAL_CACHE, "Item")
        else:
            module.GLOBAL_CACHE.Item.Properties.GetQuantity = original_get_quantity


def _test_normal_materials_warning_blue_gold_and_purple(module) -> None:
    blue_status, blue_state, _blue_widget = _run_normal_materials_warning_case(
        module,
        rarity="Blue",
        configure_state=lambda state: (
            setattr(state, "show_popup_on_start", False),
            setattr(state, "complete_without_popup", True),
        ),
    )
    _expect(blue_status == "salvaged_item_gone", "Blue normal Materials salvage should complete without a warning.")
    _expect(not any(event[0] in {"yes", "no"} for event in blue_state.events), "Blue salvage must not click warning controls.")

    for rarity in ("Gold", "Purple"):
        status, state, _widget = _run_normal_materials_warning_case(module, rarity=rarity)
        yes_events = [event for event in state.events if event[0] == "yes"]
        event_names = [str(event[0]) for event in state.events]
        _expect(status == "salvaged_item_gone", f"{rarity} normal Materials salvage should confirm and complete.")
        _expect(yes_events == [("yes", 903)], f"{rarity} should click only the named Materials Yes control.")
        _expect(
            event_names.index("start") < event_names.index("wait") < event_names.index("yes"),
            f"{rarity} should confirm in a later update cycle.",
        )


