def _test_normal_materials_warning_close_and_completion_failures(module) -> None:
    close_status, close_state, _close_widget = _run_normal_materials_warning_case(
        module,
        rarity="Gold",
        configure_state=lambda state: (
            setattr(state, "close_on_yes", False),
            setattr(state, "remove_item_on_yes", False),
        ),
    )
    _expect(close_status == "failed", "A warning that stays open after Yes must fail closed.")
