def _test_scoped_salvage_pass_drains_planned_stackable_item(module) -> None:
    widget = _make_widget(module)
    widget.salvage_settings = module.SalvageSettings(
        rules=[
            module.SalvageRule(
                enabled=True,
                model_ids=[835, 836],
                salvage_option=module.SALVAGE_OPTION_MATERIALS,
            )
        ]
    )
    quantity_by_item_id = {83540: 3, 83640: 3}
    salvage_calls: list[tuple[int, int]] = []

    def _live_item(item_id: int):
        quantity = max(0, int(quantity_by_item_id.get(int(item_id), 0)))
        if quantity <= 0:
            return None
        return _make_item(
            module,
            item_id=int(item_id),
            model_id=835 if int(item_id) == 83540 else 836,
            name="Planned Stack" if int(item_id) == 83540 else "Unplanned Stack",
            quantity=quantity,
            rarity="White",
            identified=True,
            salvageable=True,
            is_stackable=True,
        )

    def _fake_salvage_one(candidate, *_args, **_kwargs):
        salvage_calls.append((int(candidate.item.item_id), int(candidate.item.quantity)))
        item_id = int(candidate.item.item_id)
        quantity_by_item_id[item_id] = max(0, int(quantity_by_item_id.get(item_id, 0)) - 1)
        if quantity_by_item_id[item_id] <= 0:
            quantity_by_item_id.pop(item_id, None)
            status = "salvaged_item_gone"
        else:
            status = "salvaged"
        if False:
            yield None
        return status

    widget._collect_inventory_items = lambda: [
        item
        for item in (_live_item(83540), _live_item(83640))
        if item is not None
    ]
    widget._build_inventory_item_info = _live_item
    widget._get_salvage_kit_id_for_option = lambda *_args, **_kwargs: 77
    widget._salvage_one_item_with_rule = _fake_salvage_one
    widget._get_inventory_signature = lambda _items=None: ()

    outcome = _drain_generator_return(
        widget._run_salvage_pass(
            running_already_marked=True,
            planned_salvage_item_ids={83540},
        )
    )

    _expect(
        salvage_calls == [(83540, 3), (83540, 2), (83540, 1)],
        "Scoped stack draining should keep repeating only the planned stack item.",
    )
    _expect(outcome.completed == 3, "Scoped stack draining should process the full planned stack.")
    _expect(outcome.timeout_failures == 0, "Scoped stack draining should not report no-progress after the last item leaves inventory.")
    _expect(83540 not in quantity_by_item_id, "The planned stack should be drained.")
    _expect(quantity_by_item_id.get(83640) == 3, "The unplanned matching stack should remain untouched.")


