def _test_execute_now_runs_planned_salvage_before_merchant_phases(module) -> None:
    widget = _make_widget(module)
    owner_rule = module._normalize_salvage_rule(
        module.SalvageRule(
            enabled=True,
            salvage_option=module.SALVAGE_OPTION_AUTO_UPGRADE,
            target_weapon_mod_identifiers=["of Defense"],
        )
    )
    planned_owner = module.PlannedSpecificUpgradeSalvageOwner(
        model_id=123,
        rule_index=0,
        rule_snapshot=owner_rule,
    )
    first_plan = module.PlanResult(
        entries=[
            module.ExecutionPlanEntry(
                "salvage",
                module.MERCHANT_TYPE_INVENTORY,
                "Feathered Crest",
                3,
                module.PLAN_STATE_WILL_EXECUTE,
                "selected model Feathered Crest; Salvage materials via Salvage Rule #1.",
                model_id=835,
            )
        ],
        supported_map=False,
        supported_reason="Merchant support unavailable.",
        salvage_item_ids=[83503],
        salvage_specific_upgrade_owners={83503: planned_owner},
        has_actions=True,
    )
    empty_plan = module.PlanResult(
        supported_map=False,
        supported_reason="Merchant support unavailable.",
        has_actions=False,
    )
    build_calls: list[dict[str, object]] = []
    salvage_calls: list[dict[str, object]] = []

    def _build_plan(**kwargs):
        build_calls.append(dict(kwargs))
        return first_plan if len(build_calls) == 1 else empty_plan

    def _fake_run_salvage_pass(**kwargs):
        salvage_calls.append(dict(kwargs))
        widget.last_salvage_summary = "Salvage during Execute processed 3 item(s)."
        if False:
            yield None
        return module.ExecutionPhaseOutcome(label="MR Salvage", measure_label="items", attempted=1, completed=3)

    widget._build_plan = _build_plan
    widget._run_salvage_pass = _fake_run_salvage_pass

    _drain_generator_return(widget._execute_now(local_only=True))

    _expect(len(build_calls) >= 2, "Execute should rebuild the plan after running planned salvage.")
    _expect(len(salvage_calls) == 1, "Execute should run the planned salvage pass once.")
    _expect(
        salvage_calls[0].get("summary_subject") == "Salvage during Execute",
        "Execute salvage should use an execution-specific summary label.",
    )
    _expect(
        set(salvage_calls[0].get("planned_salvage_item_ids") or set()) == {83503},
        "Execute should scope salvage to the rebuilt plan's executable salvage IDs.",
    )
    _expect(
        salvage_calls[0].get("planned_specific_upgrade_owners") == first_plan.salvage_specific_upgrade_owners,
        "Execute should pass the final live plan's Specific owner map into scoped Salvage.",
    )
    _expect(
        "Salvage during Execute processed 3 item(s)." in widget.last_execution_summary,
        "Execute summary should include the salvage phase result.",
    )
    _expect(not widget.preview_ready, "Successful execute-time salvage should mark the preview stale.")


def _test_execute_now_stops_when_planned_salvage_fails(module) -> None:
    widget = _make_widget(module)
    first_plan = module.PlanResult(
        entries=[
            module.ExecutionPlanEntry(
                "salvage",
                module.MERCHANT_TYPE_INVENTORY,
                "Feathered Crest",
                2,
                module.PLAN_STATE_WILL_EXECUTE,
                "selected model Feathered Crest; Salvage materials via Salvage Rule #1.",
                model_id=835,
            )
        ],
        supported_map=True,
        supported_reason="Ready.",
        salvage_item_ids=[83504],
        merchant_sell_item_ids=[90001],
        has_actions=True,
    )
    merchant_phase_called: list[str] = []

    def _fake_run_salvage_pass(**kwargs):
        widget.last_salvage_summary = "Salvage during Execute found matching items, but none were confirmed salvaged. 1 timeout/failure(s)."
        if False:
            yield None
        return module.ExecutionPhaseOutcome(label="MR Salvage", measure_label="items", attempted=1, timeout_failures=1)

    def _fail_merchant_phase(*_args, **_kwargs):
        merchant_phase_called.append("merchant")
        if False:
            yield None
        return module.ExecutionPhaseOutcome(label="Merchant sells", measure_label="items")

    widget._build_plan = lambda **_kwargs: first_plan
    widget._run_salvage_pass = _fake_run_salvage_pass
    widget._execute_merchant_sell_phase = _fail_merchant_phase

    _drain_generator_return(widget._execute_now())

    _expect(not merchant_phase_called, "Execute should not continue into merchant phases after salvage failure.")
    _expect(
        widget.status_message == "Salvage during Execute did not finish safely; merchant actions were not run.",
        "Execute should report a safe stop after planned salvage failure.",
    )


