class _FakeExactUpgradeSalvageBridge:
    def __init__(
        self,
        module,
        *,
        available: bool = True,
        result=None,
        unavailable_reason: str = "fake backend unavailable",
    ):
        self.module = module
        self.available = bool(available)
        self.result = (
            result
            if result is not None
            else module._ExactUpgradeSalvageBridgeResult(True, "processed", "")
        )
        self.unavailable_reason = unavailable_reason
        self.availability_checks = 0
        self.calls: list[dict[str, object]] = []

    def get_upgrade_for_option(self, _item_id: int, option: object):
        canonical_by_option = {
            self.module.SALVAGE_OPTION_PREFIX: "Cruel",
            self.module.SALVAGE_OPTION_SUFFIX: "OfDefense",
            self.module.SALVAGE_OPTION_INSCRIPTION: "AptitudeNotAttitude",
        }
        return canonical_by_option.get(str(option or "")), ""

    def is_available(self):
        self.availability_checks += 1
        return self.available, "" if self.available else self.unavailable_reason

    def salvage_exact_upgrade(
        self,
        item_id: int,
        option: object,
        *,
        expected_upgrade: str | None = None,
        preferred_kit_id: int = 0,
        timeout_ms: int = 0,
        debug_enabled: bool = False,
    ):
        self.calls.append(
            {
                "item_id": int(item_id),
                "option": option,
                "expected_upgrade": str(expected_upgrade or ""),
                "preferred_kit_id": int(preferred_kit_id),
                "timeout_ms": int(timeout_ms),
                "debug_enabled": bool(debug_enabled),
            }
        )
        if False:
            yield None
        return self.result


def _install_fake_exact_salvage_bridge(widget, fake_bridge: _FakeExactUpgradeSalvageBridge) -> None:
    widget._exact_upgrade_salvage_bridge = fake_bridge
    widget._salvage_upgrade_support_cache = None


def _make_salvage_candidate(module, item, rule, *, reason: str = "specific upgrade target"):
    return module.SalvageCandidate(
        item=item,
        rule_index=0,
        rule=rule,
        reason=reason,
    )


