def _test_merchant_rules_local_frame_safety(module) -> None:
    frame_guard = module._MerchantRulesSalvageFrameGuard
    root_key = module.FrameId.SalvageWindow
    container_key = root_key.Options
    action_key = container_key.Option1
    zero_width_key = container_key.Option2
    reversed_key = container_key.Option3
    cycle_a_key = container_key.Option4
    cycle_b_key = root_key.Button
    uncreated_key = root_key.CancelButton
    extra_key = root_key.OptionsWindowConfirmMaterialsWindow

    module.Frame.reset()
    try:
        module.Frame.configure(root_key)
        module.Frame.configure(container_key, parent=root_key)
        module.Frame.configure(action_key, parent=container_key)
        module.Frame.configure(zero_width_key, parent=container_key, coords=(10, 10, 10, 30))
        module.Frame.configure(reversed_key, parent=container_key, coords=(20, 20, 10, 10))
        module.Frame.configure(cycle_a_key, parent=cycle_b_key)
        module.Frame.configure(cycle_b_key, parent=cycle_a_key)
        module.Frame.configure(uncreated_key, created=False)
        module.Frame.configure(extra_key)

        _expect(
            frame_guard.is_frame_effectively_visible(module.Frame(action_key)),
            "A visible named frame and its ancestors should be accepted.",
        )
        module.Frame.configure(action_key, parent=container_key, visible=False)
        _expect(
            not frame_guard.is_frame_effectively_visible(module.Frame(action_key)),
            "A hidden named frame must be rejected.",
        )
        module.Frame.configure(action_key, parent=container_key)
        module.Frame.configure(root_key, visible=False)
        _expect(
            not frame_guard.is_frame_effectively_visible(module.Frame(action_key)),
            "A hidden ancestor must be rejected.",
        )
        module.Frame.configure(root_key)

        _expect(
            not frame_guard.is_frame_effectively_visible(module.Frame(module.FrameId.Merchant)),
            "An unresolved named frame must be rejected.",
        )

        class _InvalidFrame:
            @property
            def exists(self):
                raise RuntimeError("named-frame lookup failed")

        _expect(
            not frame_guard.is_frame_effectively_visible(_InvalidFrame()),
            "Named-frame resolution exceptions must fail closed.",
        )
        _expect(
            not frame_guard.is_frame_effectively_visible(module.Frame(cycle_a_key)),
            "An ancestor cycle must be rejected.",
        )
        _expect(
            not frame_guard.is_frame_effectively_visible(module.Frame(uncreated_key)),
            "An uncreated named frame must be rejected.",
        )
        _expect(
            not frame_guard.is_frame_actionable(module.Frame(zero_width_key)),
            "A zero-width control must not be actionable.",
        )
        _expect(
            not frame_guard.is_frame_actionable(module.Frame(reversed_key)),
            "Invalid reversed dimensions must not be actionable.",
        )
        _expect(
            frame_guard.is_frame_actionable(module.Frame(action_key)),
            "A visible positive-size named control should be actionable.",
        )

        module.Frame.configure(action_key, parent=object())
        _expect(
            not frame_guard.is_frame_effectively_visible(module.Frame(action_key)),
            "Ancestor resolution exceptions must fail closed.",
        )
        module.Frame.configure(action_key, parent=container_key)
        _expect(
            frame_guard.is_hierarchy_active(
                module.Frame(root_key),
                required_visible_frames=(module.Frame(container_key), module.Frame(extra_key)),
                required_actionable_frames=(module.Frame(action_key), module.Frame(extra_key)),
            ),
            "The local hierarchy helper should support multiple named-frame requirements.",
        )
    finally:
        module.Frame.reset()


def _test_merchant_rules_local_popup_cancellation_order(module) -> None:
    state = _FakeSlotSalvageState()
    bridge, restore = _prepare_slot_salvage_bridge(module, state)
    try:
        available, reason = bridge.is_available()
        _expect(available and reason == "", "The Merchant Rules-local popup helpers should load.")
        state.options_open = True
        state.current_warning = True
        state.expert_window = True
        state.material_window = True

        for expected_popup in ("options", "current_warning", "expert", "material"):
            active_popup = bridge._get_active_salvage_popup()
            _expect(active_popup is not None, f"{expected_popup} should be detected as active.")
            _expect(
                bridge._cancel_active_salvage_choice_dialog(active_popup),
                f"{expected_popup} should cancel safely.",
            )
            _expect(
                state.cancelled_popups[-1] == expected_popup,
                "Active stale popups should follow the established cancellation order.",
            )

        _expect(
            bridge._get_active_salvage_popup() is None,
            "No popup should remain active after ordered cancellation.",
        )
        _expect(
            not bridge._cancel_active_salvage_choice_dialog(),
            "Cancellation should fail closed when none is active.",
        )
    finally:
        restore()


def _test_merchant_rules_popup_resolution_requires_complete_cancel_and_skips_invalid(module) -> None:
    state = _FakeSlotSalvageState()
    bridge, restore = _prepare_slot_salvage_bridge(module, state)
    try:
        _expect(
            bridge._get_active_salvage_popup() is None,
            "No unnamed or obsolete salvage hierarchy should be considered.",
        )

        state.options_open = True
        state.current_warning = True
        state.missing_frame_ids.add(403)
        active_popup = bridge._get_active_salvage_popup()
        _expect(
            active_popup is not None
            and active_popup.cancel_frame.key
            is module.FrameId.ScreenFrame.C6.SalvageMaterialsDialog.NoButton,
            "An incomplete named Options candidate must be skipped for the valid Materials warning.",
        )

        state.options_open = False
        state.missing_frame_ids.clear()
        state.expert_window = True
        current_cancel = module.FrameId.ScreenFrame.C6.SalvageMaterialsDialog.NoButton
        module.Frame.configure(
            current_cancel,
            parent=module.FrameId.ScreenFrame.C6.SalvageMaterialsDialog,
            coords=(10, 10, 10, 10),
        )
        active_popup = bridge._get_active_salvage_popup()
        _expect(
            active_popup is not None
            and active_popup.cancel_frame.key
            is module.FrameId.ScreenFrame.C6.ExpertSalvageUnidentifiedItem.Cancel,
            "A Materials warning with a non-actionable No control must be skipped.",
        )

        state.current_warning = False
        state.material_window = True
        expert_cancel = module.FrameId.ScreenFrame.C6.ExpertSalvageUnidentifiedItem.Cancel
        module.Frame.configure(
            expert_cancel,
            parent=module.FrameId.ScreenFrame.C6.ExpertSalvageUnidentifiedItem,
            visible=False,
        )
        active_popup = bridge._get_active_salvage_popup()
        _expect(
            active_popup is not None
            and active_popup.cancel_frame.key
            is module.FrameId.SalvageWindow.OptionsWindowConfirmMaterialsWindow.Cancel,
            "An expert warning with a hidden Cancel control must be skipped.",
        )
    finally:
        restore()

    replacement_state = _FakeSlotSalvageState()
    replacement_state.current_warning = True
    bridge, restore = _prepare_slot_salvage_bridge(module, replacement_state)
    try:
        active_popup = bridge._get_active_salvage_popup()
        _expect(active_popup is not None, "A current warning should produce one captured named popup.")
        replacement_state.frame_generation += 1
        _expect(
            not bridge._cancel_active_salvage_choice_dialog(active_popup),
            "A captured popup whose widget instances were replaced must not be clicked.",
        )
        _expect(
            not replacement_state.events,
            "Popup-instance replacement must fail closed without clicking the replacement No control.",
        )
    finally:
        restore()


def _test_merchant_rules_local_exact_option_validation(module) -> None:
    state = _FakeSlotSalvageState()
    state.options_open = True
    bridge, restore = _prepare_slot_salvage_bridge(module, state)
    try:
        available, reason = bridge.is_available()
        _expect(available and reason == "", "The Merchant Rules-local exact-option helper should load.")
        expected_frames = {
            _FakeSalvageMode.Prefix: module.FrameId.SalvageWindow.Options.Option1,
            _FakeSalvageMode.Suffix: module.FrameId.SalvageWindow.Options.Option2,
            _FakeSalvageMode.Inscription: module.FrameId.SalvageWindow.Options.Option3,
        }
        for mode, expected_key in expected_frames.items():
            resolved_frame = bridge._get_active_exact_option_frame(mode)
            _expect(
                resolved_frame is not None and resolved_frame.key is expected_key,
                f"{mode.name} should resolve only its exact actionable named frame.",
            )

        _expect(
            bridge._get_active_exact_option_frame(_FakeSalvageMode.Materials) is None,
            "Exact-upgrade extraction must never accept the Materials frame.",
        )

        state.zero_size_frame_ids.add(501)
        _expect(
            bridge._get_active_exact_option_frame(_FakeSalvageMode.Suffix) is None,
            "A zero-size exact option must fail closed.",
        )
        state.zero_size_frame_ids.clear()

        state.hidden_frame_ids.add(402)
        _expect(
            bridge._get_active_exact_option_frame(_FakeSalvageMode.Prefix) is None,
            "A hidden required options container must make the exact option inactive.",
        )
    finally:
        restore()


class _FakeExactSlot(enum.IntEnum):
    Prefix = 1
    Suffix = 2
    Inscription = 3


class _FakeSalvageMode(enum.IntEnum):
    Prefix = 4
    Suffix = 5
    Inscription = 6
    Materials = 7


class _FakeSlotSalvageState:
    def __init__(self, *, item_id: int = 1001):
        self.item_id = int(item_id)
        self.item_present = True
        self.upgrades: dict[_FakeExactSlot, str] = {}
        self.options_open = False
        self.inactive_frames_exist = False
        self.stale_window = False
        self.unexpected_window = False
        self.current_warning = False
        self.current_warning_on_start = False
        self.expert_window = False
        self.material_window = False
        self.popup_appears = True
        self.confirm_visible = True
        self.confirm_actionable = True
        self.visible_modes = {
            _FakeSalvageMode.Prefix,
            _FakeSalvageMode.Suffix,
            _FakeSalvageMode.Inscription,
        }
        self.selected_mode: _FakeSalvageMode | None = None
        self.replace_on_start: tuple[_FakeExactSlot, str] | None = None
        self.replace_after_select: tuple[_FakeExactSlot, str] | None = None
        self.replace_frame_after_select = False
        self.remove_on_confirm = True
        self.frame_generation = 0
        self.events: list[tuple[object, ...]] = []
        self.cancelled_popups: list[str] = []
        self.missing_frame_ids: set[int] = set()
        self.hidden_frame_ids: set[int] = set()
        self.zero_size_frame_ids: set[int] = set()


def _install_fake_slot_salvage_runtime(module, state: _FakeSlotSalvageState):
    original_item_module = sys.modules.get("Py4GWCoreLib.Item")
    original_ui_module = sys.modules.get("Py4GWCoreLib.UIManager")
    item_enums_module = sys.modules["Py4GWCoreLib.enums_src.Item_enums"]
    had_salvage_mode = hasattr(item_enums_module, "SalvageMode")
    original_salvage_mode = getattr(item_enums_module, "SalvageMode", None)

    mode_to_slot = {
        _FakeSalvageMode.Prefix: _FakeExactSlot.Prefix,
        _FakeSalvageMode.Suffix: _FakeExactSlot.Suffix,
        _FakeSalvageMode.Inscription: _FakeExactSlot.Inscription,
    }
    frame_id = module.FrameId
    options_root = frame_id.SalvageWindow
    options_container = options_root.Options
    options_cancel = options_root.CancelButton
    confirm_frame = options_root.Button
    frame_keys = {
        _FakeSalvageMode.Prefix: options_container.Option1,
        _FakeSalvageMode.Suffix: options_container.Option2,
        _FakeSalvageMode.Inscription: options_container.Option3,
        _FakeSalvageMode.Materials: options_container.Option4,
    }
    frame_numbers = {
        options_root.path: 401,
        options_container.path: 402,
        options_cancel.path: 403,
        confirm_frame.path: 404,
        frame_keys[_FakeSalvageMode.Prefix].path: 500,
        frame_keys[_FakeSalvageMode.Suffix].path: 501,
        frame_keys[_FakeSalvageMode.Inscription].path: 502,
        frame_keys[_FakeSalvageMode.Materials].path: 503,
    }

    def _frame_exists(key) -> bool:
        return int(frame_numbers.get(key.path, 0)) not in state.missing_frame_ids

    def _frame_visible(key, default_visible) -> bool:
        frame_number = int(frame_numbers.get(key.path, 0))
        return bool(_frame_exists(key) and frame_number not in state.hidden_frame_ids and default_visible())

    def _frame_coords(key, *, confirm: bool = False):
        frame_number = int(frame_numbers.get(key.path, 0))
        if frame_number in state.zero_size_frame_ids or (confirm and not state.confirm_actionable):
            return (10, 10, 10, 10)
        return (10, 10, 110, 30)

    def options_active() -> bool:
        return bool(state.options_open or state.stale_window)

    def locally_allocated() -> bool:
        return bool(options_active() or state.inactive_frames_exist)

    def _cancel_popup(popup_kind: str) -> None:
        state.events.append(("cancel",))
        state.cancelled_popups.append(popup_kind)
        if popup_kind == "options":
            state.options_open = False
            state.stale_window = False
        elif popup_kind == "current_warning":
            state.current_warning = False
            state.unexpected_window = False
        elif popup_kind == "expert":
            state.expert_window = False
        elif popup_kind == "material":
            state.material_window = False

    module.Frame.reset()
    module.Frame.configure(
        options_root,
        exists=lambda: _frame_exists(options_root),
        visible=lambda: _frame_visible(options_root, options_active),
        widget_id=lambda: f"options-root@{state.frame_generation}",
    )
    module.Frame.configure(
        options_container,
        exists=lambda: _frame_exists(options_container),
        visible=lambda: _frame_visible(options_container, locally_allocated),
        parent=options_root,
        widget_id=lambda: f"options-container@{state.frame_generation}",
    )
    module.Frame.configure(
        options_cancel,
        exists=lambda: _frame_exists(options_cancel),
        visible=lambda: _frame_visible(options_cancel, locally_allocated),
        coords=lambda: _frame_coords(options_cancel),
        parent=options_root,
        widget_id=lambda: f"options-cancel@{state.frame_generation}",
        on_click=lambda: _cancel_popup("options"),
    )
    module.Frame.configure(
        confirm_frame,
        exists=lambda: _frame_exists(confirm_frame),
        visible=lambda: _frame_visible(confirm_frame, lambda: locally_allocated() and state.confirm_visible),
        coords=lambda: _frame_coords(confirm_frame, confirm=True),
        parent=options_root,
        widget_id=lambda: f"options-confirm@{state.frame_generation}",
    )
    for mode, key in frame_keys.items():
        module.Frame.configure(
            key,
            exists=lambda current_key=key: _frame_exists(current_key),
            visible=lambda current_key=key, current_mode=mode: _frame_visible(
                current_key,
                lambda: locally_allocated() and current_mode in state.visible_modes,
            ),
            coords=lambda current_key=key: _frame_coords(current_key),
            parent=options_container,
            widget_id=lambda current_key=key: f"{current_key.path}@{state.frame_generation}",
        )

    current_warning_root = frame_id.ScreenFrame.C6.SalvageMaterialsDialog
    current_warning_cancel = current_warning_root.NoButton
    current_warning_confirm = current_warning_root.YesButton
    expert_root = frame_id.ScreenFrame.C6.ExpertSalvageUnidentifiedItem
    expert_cancel = expert_root.Cancel
    material_root = frame_id.SalvageWindow.OptionsWindowConfirmMaterialsWindow
    material_cancel = material_root.Cancel

    module.Frame.configure(
        current_warning_root,
        visible=lambda: bool(state.current_warning or state.unexpected_window),
        widget_id=lambda: f"current-warning-root@{state.frame_generation}",
    )
    module.Frame.configure(
        current_warning_cancel,
        visible=lambda: bool(state.current_warning or state.unexpected_window),
        parent=current_warning_root,
        widget_id=lambda: f"current-warning-cancel@{state.frame_generation}",
        on_click=lambda: _cancel_popup("current_warning"),
    )
    module.Frame.configure(
        current_warning_confirm,
        visible=lambda: bool(state.current_warning or state.unexpected_window),
        parent=current_warning_root,
        widget_id=lambda: f"current-warning-confirm@{state.frame_generation}",
        on_click=lambda: (
            state.events.append(("materials_yes",)),
            setattr(state, "current_warning", False),
        ),
    )
    module.Frame.configure(
        expert_root,
        visible=lambda: state.expert_window,
        widget_id=lambda: f"expert-root@{state.frame_generation}",
    )
    module.Frame.configure(
        expert_cancel,
        visible=lambda: state.expert_window,
        parent=expert_root,
        widget_id=lambda: f"expert-cancel@{state.frame_generation}",
        on_click=lambda: _cancel_popup("expert"),
    )
    module.Frame.configure(
        material_root,
        visible=lambda: state.material_window,
        widget_id=lambda: f"material-root@{state.frame_generation}",
    )
    module.Frame.configure(
        material_cancel,
        visible=lambda: state.material_window,
        parent=material_root,
        widget_id=lambda: f"material-cancel@{state.frame_generation}",
        on_click=lambda: _cancel_popup("material"),
    )

    class FakeMods:
        Slot = _FakeExactSlot

        @staticmethod
        def GetUpgrades(item_id: int):
            if not state.item_present or int(item_id) != state.item_id:
                return []
            return [(name, slot) for slot, name in sorted(state.upgrades.items(), key=lambda entry: int(entry[0]))]

    class FakeSalvageOptionsWindow:
        @staticmethod
        def IsOpen() -> bool:
            return bool(options_active())

        @staticmethod
        def GetSalvageOptionFrame(mode):
            key = frame_keys.get(mode)
            return module.Frame(key) if key is not None and FakeSalvageOptionsWindow.IsOpen() else None

        @staticmethod
        def IsOptionVisible(mode) -> bool:
            frame = FakeSalvageOptionsWindow.GetSalvageOptionFrame(mode)
            return bool(frame is not None and frame.is_usable)

        @staticmethod
        def SelectOption(mode) -> bool:
            if not FakeSalvageOptionsWindow.IsOptionVisible(mode):
                return False
            state.selected_mode = mode
            state.events.append(("select", mode))
            if state.replace_after_select is not None:
                slot, replacement = state.replace_after_select
                state.upgrades[slot] = replacement
            if state.replace_frame_after_select:
                state.frame_generation += 1
            return True

        @staticmethod
        def Confirm() -> bool:
            if (
                not FakeSalvageOptionsWindow.IsOpen()
                or not module.Frame(confirm_frame).is_usable
                or state.selected_mode is None
            ):
                return False
            state.events.append(("confirm", state.selected_mode))
            if state.remove_on_confirm:
                state.upgrades.pop(mode_to_slot[state.selected_mode], None)
            state.options_open = False
            return True

    fake_item_module = types.ModuleType("Py4GWCoreLib.Item")
    fake_item_module.Item = types.SimpleNamespace(Mods=FakeMods)
    fake_ui_module = types.ModuleType("Py4GWCoreLib.UIManager")
    fake_ui_module.SalvageOptionsWindow = FakeSalvageOptionsWindow
    sys.modules["Py4GWCoreLib.Item"] = fake_item_module
    sys.modules["Py4GWCoreLib.UIManager"] = fake_ui_module
    item_enums_module.SalvageMode = _FakeSalvageMode

    def _restore() -> None:
        if original_item_module is None:
            sys.modules.pop("Py4GWCoreLib.Item", None)
        else:
            sys.modules["Py4GWCoreLib.Item"] = original_item_module
        if original_ui_module is None:
            sys.modules.pop("Py4GWCoreLib.UIManager", None)
        else:
            sys.modules["Py4GWCoreLib.UIManager"] = original_ui_module
        if had_salvage_mode:
            item_enums_module.SalvageMode = original_salvage_mode
        else:
            delattr(item_enums_module, "SalvageMode")
        module.Frame.reset()

    return _restore


def _prepare_slot_salvage_bridge(module, state: _FakeSlotSalvageState):
    restore_runtime = _install_fake_slot_salvage_runtime(module, state)
    widget = _make_widget(module)
    widget._get_inventory_item_ids = lambda: [state.item_id] if state.item_present else []

    def _start(item_id: int, kit_id: int, attempt: int):
        state.events.append(("start", int(item_id), int(kit_id), int(attempt)))
        if state.replace_on_start is not None:
            slot, replacement = state.replace_on_start
            state.upgrades[slot] = replacement
        if state.current_warning_on_start:
            state.current_warning = True
            state.options_open = False
        elif state.unexpected_window:
            state.options_open = False
        elif state.popup_appears:
            state.options_open = True
        if False:
            yield None
        return True

    widget._queue_salvage_start = _start
    original_wait = module.Routines.Yield.wait

    def _wait(milliseconds: int):
        state.events.append(("wait", int(milliseconds)))
        yield int(milliseconds)

    module.Routines.Yield.wait = _wait

    def _restore() -> None:
        module.Routines.Yield.wait = original_wait
        restore_runtime()

    return widget._get_exact_upgrade_salvage_bridge(), _restore


