def _test_standard_rune_generic_carrier_identity_and_planning(module) -> None:
    fixture = _install_standard_rune_catalog_fixture(module)
    try:
        insignia = fixture["Dreadnought Insignia [Warrior]"]
        air = fixture["Elementalist Rune of Superior Air Magic"]
        raw_modifiers = (
            (9224, 1, 250),
            (9224, 0, 189),
            (8680, 8, 3),
            (8408, 0, 75),
        )
        state = module._parse_exact_armor_upgrade_state(
            raw_modifiers,
            module.ItemType.Salvage,
            151872,
            parsed_modifiers=_parsed_armor_matches(insignia, air),
        )
        _expect(not state.error, f"The standard Rune carrier should parse safely: {state.error}")
        air_identity = next(upgrade for upgrade in state.upgrades if upgrade.identifier == air.identifier)
        insignia_identity = next(upgrade for upgrade in state.upgrades if upgrade.identifier == insignia.identifier)
        _expect(
            air_identity.generic_carrier_upgrade_id == int(module.ItemUpgradeId.SuperiorElementalistRune),
            "Superior Air should resolve its generic carrier through ItemUpgradeId metadata.",
        )
        _expect(
            air_identity.signature == ((8680, 8, 3), (8408, 0, 75)),
            "The exact Air Rune effect signature must remain part of the identity.",
        )
        _expect(
            insignia_identity.option == module.SALVAGE_OPTION_PREFIX,
            "The Dreadnought Insignia must remain a Prefix identity.",
        )

        item = _make_item(
            module,
            item_id=160,
            model_id=151872,
            name="Dreadnought Jade Brotherhood Armguard of Superior Air Magic",
            identified=True,
            salvageable=True,
            is_armor_piece=True,
            item_type_id=int(module.ItemType.Salvage.value),
            item_type_name="Salvage",
        )
        item.raw_modifiers = raw_modifiers
        item.armor_upgrade_identifiers = [upgrade.identifier for upgrade in state.upgrades]
        item.armor_upgrade_matches = list(state.upgrades)
        item.armor_upgrade_parse_error = ""

        air_rule = module._normalize_salvage_rule(
            module.SalvageRule(
                enabled=True,
                salvage_option=module.SALVAGE_OPTION_AUTO_UPGRADE,
                target_armor_upgrade_identifiers=[air.identifier],
            )
        )
        widget = _make_widget(module)
        target_matches = widget._get_salvage_rule_armor_upgrade_target_matches(air_rule, item)
        _expect(
            len(target_matches) == 1
            and target_matches[0].identifier == air.identifier
            and target_matches[0].required_option == module.SALVAGE_OPTION_SUFFIX,
            "Specific upgrade matching must resolve the exact Air Rune and Suffix operation.",
        )
        resolution = widget._get_auto_salvage_upgrade_slot_resolution(air_rule, item)
        _expect(
            resolution.selected_option == module.SALVAGE_OPTION_SUFFIX and not resolution.block_reason,
            "Specific upgrade inference must select the Rune Suffix slot.",
        )
        widget.salvage_settings = _salvage_settings(module, rules=[air_rule])
        widget._get_salvage_kit_id_for_option = lambda *_args, **_kwargs: 777
        widget._get_armor_salvage_upgrade_support_status = lambda: (True, "")
        candidates, blocked = widget._collect_salvage_candidates(
            [item],
            [],
            require_salvage_kit=True,
        )
        _expect(len(candidates) == 1 and not blocked, "The live-shaped Air Rune item should be a salvage candidate.")
        plan = module.PlanResult()
        widget._plan_salvage_actions(plan, [item], [], set())
        _expect(
            plan.salvage_item_ids == [160]
            and any(entry.action_type == "salvage" and entry.state == module.PLAN_STATE_WILL_EXECUTE for entry in plan.entries),
            "Planning must produce one executable Specific upgrade salvage action.",
        )

        wrong_target_rule = module._normalize_salvage_rule(
            module.SalvageRule(
                enabled=True,
                salvage_option=module.SALVAGE_OPTION_AUTO_UPGRADE,
                target_armor_upgrade_identifiers=[fixture["Elementalist Rune of Superior Fire Magic"].identifier],
            )
        )
        _expect(
            not widget._get_salvage_rule_upgrade_target_matches(wrong_target_rule, item),
            "A Fire Rune target must not match the Air Rune merely because the generic carrier is Elementalist.",
        )
        _expect(
            not widget._get_salvage_rule_upgrade_target_matches(
                module._normalize_salvage_rule(
                    module.SalvageRule(
                        enabled=True,
                        salvage_option=module.SALVAGE_OPTION_AUTO_UPGRADE,
                        target_armor_upgrade_identifiers=["Warrior Rune of Superior Strength"],
                    )
                ),
                item,
            ),
            "A different-profession Rune target must remain blocked.",
        )

        for bad_raw, expected_fragment in (
            (raw_modifiers + ((9224, 0, 190),), "unknown or malformed Rune/Insignia carrier"),
            (raw_modifiers + ((9224, 0, 189),), "duplicate non-Tooltip"),
            (((9224, 0, 189), (8680, 8, 3), ("bad", 0, 0)), "malformed raw modifier tuple"),
            (((9224, 1, 250), (8680, 8, 3), (8408, 0, 75)), "authoritative generic Rune carrier"),
            (((9224, 0, 189), (8680, 8, 3), (8408, 0, 75)), "Dreadnought Insignia"),
        ):
            parsed = _parsed_armor_matches(insignia, air)
            bad_state = module._parse_exact_armor_upgrade_state(
                bad_raw,
                module.ItemType.Salvage,
                151872,
                parsed_modifiers=parsed,
            )
            _expect(bool(bad_state.error), f"Malformed or conflicting carrier case must fail closed: {bad_state.error}")
            _expect(expected_fragment in bad_state.error, f"Carrier failure should report {expected_fragment!r}.")

        for identifier, carrier_id, attribute_value in (
            ("Elementalist Rune of Minor Air Magic", 0x00B1, 1),
            ("Elementalist Rune of Major Air Magic", 0x00B7, 2),
        ):
            tier_rune = fixture[identifier]
            tier_state = module._parse_exact_armor_upgrade_state(
                ((9224, 0, carrier_id), (8680, 8, attribute_value)),
                module.ItemType.Salvage,
                151872,
                parsed_modifiers=_parsed_armor_matches(tier_rune),
            )
            _expect(not tier_state.error, f"{identifier} should resolve its generic carrier: {tier_state.error}")
            _expect(
                tier_state.upgrades[0].generic_carrier_upgrade_id == carrier_id,
                f"{identifier} should use its authoritative tier carrier.",
            )

        neutral = fixture["Rune of Superior Vigor"]
        neutral_state = module._parse_exact_armor_upgrade_state(
            ((9224, 1, 1),),
            module.ItemType.Salvage,
            151872,
            parsed_modifiers=_parsed_armor_matches(neutral),
        )
        _expect(not neutral_state.error, f"Neutral Rune carrier behavior must remain valid: {neutral_state.error}")
        neutral_identity = neutral_state.upgrades[0]
        _expect(
            neutral_identity.generic_carrier_upgrade_id is None
            and neutral_identity.option == module.SALVAGE_OPTION_SUFFIX,
            "Neutral Rune carriers already represented in the catalog must not be remapped.",
        )
        insignia_rule = module._normalize_salvage_rule(
            module.SalvageRule(
                enabled=True,
                salvage_option=module.SALVAGE_OPTION_AUTO_UPGRADE,
                target_armor_upgrade_identifiers=[insignia.identifier],
            )
        )
        insignia_matches = widget._get_salvage_rule_armor_upgrade_target_matches(insignia_rule, item)
        insignia_resolution = widget._get_auto_salvage_upgrade_slot_resolution(insignia_rule, item)
        _expect(
            len(insignia_matches) == 1
            and insignia_resolution.selected_option == module.SALVAGE_OPTION_PREFIX,
            "Insignia matching and Prefix inference must remain unchanged.",
        )
        expected_snapshot = module.ArmorUpgradeSnapshot(
            item_id=160,
            model_id=151872,
            item_type_id=int(module.ItemType.Salvage.value),
            name=item.name,
            raw_modifiers=raw_modifiers,
            upgrades=state.upgrades,
        )
        remaining_snapshot = module.ArmorUpgradeSnapshot(
            item_id=160,
            model_id=151872,
            item_type_id=int(module.ItemType.Salvage.value),
            name=item.name,
            raw_modifiers=((9224, 1, 250),),
            upgrades=(insignia_identity,),
        )
        _expect(
            not module._get_armor_upgrade_post_extraction_error(
                expected_snapshot,
                remaining_snapshot,
                air_identity,
            ),
            "Post-extraction verification should allow the Rune carrier and effects to disappear together.",
        )
        carrier_remaining_snapshot = module.ArmorUpgradeSnapshot(
            item_id=160,
            model_id=151872,
            item_type_id=int(module.ItemType.Salvage.value),
            name=item.name,
            raw_modifiers=((9224, 1, 250), (9224, 0, 189)),
            upgrades=(insignia_identity,),
        )
        _expect(
            "selected generic Rune carrier remains"
            in module._get_armor_upgrade_post_extraction_error(
                expected_snapshot,
                carrier_remaining_snapshot,
                air_identity,
            ),
            "Post-extraction verification must reject a Rune carrier left behind without its effects.",
        )
    finally:
        fixture["restore"]()


