def _test_jade_armor_multiplicity_and_linkage_variants_fail_closed(module) -> None:
    fixture = _install_jade_armor_catalog_fixture(module)
    try:
        raw_modifiers = _jade_armor_raw_modifiers()
        parsed_both = _parsed_armor_matches(fixture["insignia"], fixture["spawning"])
        shared_upgrades = _shared_jade_armor_upgrades()

        def _parse(
            raw: tuple[tuple[int, int, int], ...],
            *,
            parsed=parsed_both,
            shared=shared_upgrades,
        ):
            return module._parse_exact_armor_upgrade_state(
                raw,
                module.ItemType.Salvage,
                679,
                parsed_modifiers=parsed,
                corroborating_upgrades=shared,
            )

        carrier_index = raw_modifiers.index((9224, 1, 64))
        attribute_index = raw_modifiers.index((8680, 36, 3))
        without_carrier = raw_modifiers[:carrier_index] + raw_modifiers[carrier_index + 1:]
        reordered = (
            without_carrier[:attribute_index]
            + ((9224, 1, 64),)
            + without_carrier[attribute_index:]
        )
        interrupted = (
            raw_modifiers[:attribute_index]
            + ((41928, 41, 0),)
            + raw_modifiers[attribute_index:]
        )
        orphaned = tuple(
            triple
            for triple in raw_modifiers
            if triple not in ((8680, 36, 3), (8408, 0, 75))
        )
        mismatched = tuple(
            (8680, 32, 3) if triple == (8680, 36, 3) else triple
            for triple in raw_modifiers
        )

        cases = (
            (
                "duplicate Insignia carrier",
                raw_modifiers + ((9224, 2, 8),),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "duplicate Rune Attribute carrier",
                raw_modifiers + ((8680, 36, 3),),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "duplicate Rune health carrier",
                raw_modifiers + ((8408, 0, 75),),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "duplicate complete Rune signature",
                raw_modifiers + ((8680, 36, 3), (8408, 0, 75)),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "duplicate non-Tooltip inherent metadata",
                raw_modifiers + ((41928, 40, 0),),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "duplicate linked carrier",
                raw_modifiers + ((9224, 1, 64),),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "second decoded carrier with different runtime flags",
                raw_modifiers + ((41992, 1, 64),),
                parsed_both,
                shared_upgrades,
                "multiple Superior Ritualist Rune linkage carriers",
            ),
            (
                "orphaned carrier",
                orphaned,
                _parsed_armor_matches(fixture["insignia"]),
                shared_upgrades,
                "orphaned or mismatched",
            ),
            (
                "reordered carrier",
                reordered,
                parsed_both,
                shared_upgrades,
                "reordered, interrupted",
            ),
            (
                "interrupted carrier",
                interrupted,
                parsed_both,
                shared_upgrades,
                "reordered, interrupted",
            ),
            (
                "mismatched carrier",
                mismatched,
                _parsed_armor_matches(fixture["insignia"], fixture["communing"]),
                _shared_jade_armor_upgrades(suffix_name="RitualistRuneOfSuperiorCommuning"),
                "orphaned or mismatched",
            ),
            (
                "unknown Upgrade carrier",
                raw_modifiers + ((9224, 1, 65),),
                parsed_both,
                shared_upgrades,
                "unknown or malformed Rune/Insignia carrier",
            ),
            (
                "duplicate silent-but-not-Tooltip metadata",
                raw_modifiers + ((49152, 0, 0),),
                parsed_both,
                shared_upgrades,
                "duplicate non-Tooltip",
            ),
            (
                "missing shared Suffix corroboration",
                raw_modifiers,
                parsed_both,
                None,
                "corroboration unavailable",
            ),
            (
                "wrong shared Suffix corroboration",
                raw_modifiers,
                parsed_both,
                _shared_jade_armor_upgrades(suffix_name="RitualistRuneOfSuperiorCommuning"),
                "did not corroborate exactly one expected named Suffix",
            ),
            (
                "duplicate shared Suffix corroboration",
                raw_modifiers,
                parsed_both,
                shared_upgrades + (("RitualistRuneOfSuperiorSpawningPower", types.SimpleNamespace(name="Suffix")),),
                "did not corroborate exactly one expected named Suffix",
            ),
            (
                "duplicate parsed catalog identity",
                raw_modifiers,
                _parsed_armor_matches(fixture["insignia"], fixture["insignia"], fixture["spawning"]),
                shared_upgrades,
                "shares a signature carrier",
            ),
            (
                "conflicting Prefix identities",
                raw_modifiers + ((9224, 1, 249),),
                _parsed_armor_matches(fixture["insignia"], fixture["knights"], fixture["spawning"]),
                shared_upgrades,
                "multiple conflicting Insignia identities",
            ),
            (
                "conflicting Suffix identities sharing one health carrier",
                raw_modifiers + ((8680, 32, 3),),
                _parsed_armor_matches(fixture["insignia"], fixture["spawning"], fixture["communing"]),
                shared_upgrades,
                "shares a signature carrier",
            ),
            (
                "malformed catalog identity",
                raw_modifiers,
                _parsed_armor_matches(fixture["malformed"]),
                shared_upgrades,
                "non-fixed or malformed catalog signature",
            ),
        )
        for label, raw, parsed, shared, expected_error in cases:
            state = _parse(raw, parsed=parsed, shared=shared)
            _expect(bool(state.error), f"{label} must fail closed.")
            _expect(expected_error in state.error, f"{label} should report {expected_error!r}; got {state.error!r}.")
    finally:
        fixture["restore"]()


def _test_jade_armor_post_extraction_signature_and_linkage_counts(module) -> None:
    fixture = _install_jade_armor_catalog_fixture(module)
    try:
        raw_modifiers = _jade_armor_raw_modifiers()
        state = module._parse_exact_armor_upgrade_state(
            raw_modifiers,
            module.ItemType.Salvage,
            679,
            parsed_modifiers=_parsed_armor_matches(fixture["insignia"], fixture["spawning"]),
            corroborating_upgrades=_shared_jade_armor_upgrades(),
        )
        _expect(not state.error, f"The pre-extraction fixture must be valid: {state.error}")
        insignia = next(upgrade for upgrade in state.upgrades if upgrade.option == module.SALVAGE_OPTION_PREFIX)
        spawning = next(upgrade for upgrade in state.upgrades if upgrade.option == module.SALVAGE_OPTION_SUFFIX)
        expected = module.ArmorUpgradeSnapshot(
            item_id=62001,
            model_id=679,
            item_type_id=int(module.ItemType.Salvage.value),
            name="Lieutenant's Jade Brotherhood Garb of Superior Spawning Power",
            raw_modifiers=raw_modifiers,
            upgrades=state.upgrades,
            linkages=state.linkages,
        )

        rune_removed_raw = tuple(
            triple
            for triple in raw_modifiers
            if triple not in {
                spawning.signature[0],
                spawning.signature[1],
                state.linkages[0].carrier,
            }
        )
        rune_removed_raw = tuple(
            triple
            for index, triple in enumerate(rune_removed_raw)
            if not (triple == (9520, 2, 129) and index % 2 == 0)
        )
        after_rune = module.ArmorUpgradeSnapshot(
            item_id=expected.item_id,
            model_id=expected.model_id,
            item_type_id=expected.item_type_id,
            name=expected.name,
            raw_modifiers=rune_removed_raw,
            upgrades=(insignia,),
            linkages=(),
        )
        _expect(
            module._get_armor_upgrade_post_extraction_error(expected, after_rune, spawning) == "",
            "Rune extraction should require both signature words and its linked carrier to disappear.",
        )

        after_insignia = module.ArmorUpgradeSnapshot(
            item_id=expected.item_id,
            model_id=expected.model_id,
            item_type_id=expected.item_type_id,
            name=expected.name,
            raw_modifiers=tuple(triple for triple in raw_modifiers if triple != insignia.signature[0]),
            upgrades=(spawning,),
            linkages=state.linkages,
        )
        _expect(
            module._get_armor_upgrade_post_extraction_error(expected, after_insignia, insignia) == "",
            "Insignia extraction should preserve both Rune words and the linked carrier.",
        )

        invalid_cases = (
            (
                "Rune Attribute property remains",
                replace(after_rune, raw_modifiers=after_rune.raw_modifiers + (spawning.signature[0],)),
                spawning,
                "signature remains",
            ),
            (
                "Rune health property remains",
                replace(after_rune, raw_modifiers=after_rune.raw_modifiers + (spawning.signature[1],)),
                spawning,
                "signature remains",
            ),
            (
                "selected Rune linkage remains",
                replace(after_rune, raw_modifiers=after_rune.raw_modifiers + (state.linkages[0].carrier,)),
                spawning,
                "linkage carrier remains",
            ),
            (
                "unselected Insignia is removed with the Rune",
                replace(
                    after_rune,
                    raw_modifiers=tuple(
                        triple for triple in after_rune.raw_modifiers if triple != insignia.signature[0]
                    ),
                ),
                spawning,
                "unselected armor upgrade signature count changed",
            ),
            (
                "unselected Rune carrier is removed with the Insignia",
                replace(
                    after_insignia,
                    raw_modifiers=tuple(
                        triple
                        for triple in after_insignia.raw_modifiers
                        if triple != state.linkages[0].carrier
                    ),
                ),
                insignia,
                "unselected Rune linkage carrier count changed",
            ),
            (
                "unselected Rune signature is altered with the Insignia",
                replace(
                    after_insignia,
                    raw_modifiers=tuple(
                        triple
                        for triple in after_insignia.raw_modifiers
                        if triple != spawning.signature[1]
                    ),
                ),
                insignia,
                "unselected armor upgrade signature count changed",
            ),
            (
                "remaining identity is replaced",
                replace(after_rune, upgrades=()),
                spawning,
                "unselected armor upgrade identity changed",
            ),
            (
                "remaining linkage identity is missing",
                replace(after_insignia, linkages=()),
                insignia,
                "linkage identity changed",
            ),
        )
        for label, current, target, expected_error in invalid_cases:
            error = module._get_armor_upgrade_post_extraction_error(expected, current, target)
            _expect(bool(error), f"{label} must fail closed.")
            _expect(expected_error in error, f"{label} should report {expected_error!r}; got {error!r}.")
    finally:
        fixture["restore"]()


def _test_jade_armor_bridge_component_and_source_outcomes(module) -> None:
    fixture = _install_jade_armor_catalog_fixture(module)
    original_wait = module.Routines.Yield.wait
    try:
        raw_modifiers = _jade_armor_raw_modifiers()
        parsed_state = module._parse_exact_armor_upgrade_state(
            raw_modifiers,
            module.ItemType.Salvage,
            679,
            parsed_modifiers=_parsed_armor_matches(fixture["insignia"], fixture["spawning"]),
            corroborating_upgrades=_shared_jade_armor_upgrades(),
        )
        _expect(not parsed_state.error, f"The bridge fixture must start valid: {parsed_state.error}")
        insignia = next(
            upgrade
            for upgrade in parsed_state.upgrades
            if upgrade.option == module.SALVAGE_OPTION_PREFIX
        )
        spawning = next(
            upgrade
            for upgrade in parsed_state.upgrades
            if upgrade.option == module.SALVAGE_OPTION_SUFFIX
        )
        expected = module.ArmorUpgradeSnapshot(
            item_id=62001,
            model_id=679,
            item_type_id=int(module.ItemType.Salvage.value),
            name="Lieutenant's Jade Brotherhood Garb of Superior Spawning Power",
            raw_modifiers=raw_modifiers,
            upgrades=parsed_state.upgrades,
            linkages=parsed_state.linkages,
        )
        after_rune = module.ArmorUpgradeSnapshot(
            item_id=expected.item_id,
            model_id=expected.model_id,
            item_type_id=expected.item_type_id,
            name=expected.name,
            raw_modifiers=tuple(
                triple
                for triple in raw_modifiers
                if triple not in {
                    spawning.signature[0],
                    spawning.signature[1],
                    parsed_state.linkages[0].carrier,
                }
            ),
            upgrades=(insignia,),
            linkages=(),
        )

        def _run_case(
            *,
            source_destroyed: bool,
            kit_model_id: int,
            target_component: bool,
            opposite_component: bool,
        ):
            state = _FakeSlotSalvageState(item_id=expected.item_id)
            restore_runtime = _install_fake_slot_salvage_runtime(module, state)
            try:
                widget = _make_widget(module)

                def _start(item_id: int, kit_id: int, attempt: int):
                    state.events.append(("start", int(item_id), int(kit_id), int(attempt)))
                    state.options_open = True
                    if False:
                        yield None
                    return True

                def _confirmed() -> bool:
                    return any(event[0] == "confirm" for event in state.events)

                def _capture_snapshot(item_id: int, *, allow_no_upgrades: bool = False):
                    _expect(int(item_id) == expected.item_id, "Bridge revalidation must remain item-bound.")
                    if not _confirmed():
                        return expected, ""
                    if source_destroyed:
                        return None, "item is no longer in carried inventory"
                    return after_rune, ""

                def _component_quantities(identity):
                    if not _confirmed():
                        return {}
                    if identity == spawning and target_component:
                        return {93001: 1}
                    if identity == insignia and opposite_component:
                        return {93002: 1}
                    return {}

                def _wait(milliseconds: int):
                    state.events.append(("wait", int(milliseconds)))
                    yield int(milliseconds)

                widget._queue_salvage_start = _start
                widget._capture_armor_upgrade_snapshot = _capture_snapshot
                widget._capture_standalone_armor_upgrade_component_quantities = _component_quantities
                widget._validate_inventory_shortcut_salvage_kit = (
                    lambda kit_id, **_kwargs: (int(kit_id), "")
                )
                widget._get_salvage_kit_model_id = lambda _kit_id: int(kit_model_id)
                widget._get_inventory_item_ids = lambda: (
                    [] if source_destroyed and _confirmed() else [expected.item_id]
                )
                widget._reserve_execute_item_ids = lambda _item_ids: None
                module.Routines.Yield.wait = _wait

                bridge = module._MerchantRulesArmorUpgradeSalvageBridge(owner=widget)
                return _drain_generator_return(
                    bridge.salvage_exact_armor_upgrade(
                        expected,
                        spawning,
                        preferred_kit_id=777,
                        timeout_ms=150,
                    )
                )
            finally:
                restore_runtime()

        no_component = _run_case(
            source_destroyed=False,
            kit_model_id=int(module.ModelID.Perfect_Salvage_Kit.value),
            target_component=False,
            opposite_component=False,
        )
        _expect(not no_component.success, "A removed signature without an extracted component must not succeed.")
        _expect(
            "semantic target removal could not be verified" in no_component.reason,
            "Missing target-component evidence should time out fail-closed.",
        )

        opposite_delta = _run_case(
            source_destroyed=False,
            kit_model_id=int(module.ModelID.Perfect_Salvage_Kit.value),
            target_component=True,
            opposite_component=True,
        )
        _expect(not opposite_delta.success, "An opposite component delta must fail even when the source survives.")
        _expect(
            "unselected armor upgrade was also extracted" in opposite_delta.reason,
            "The surviving-source failure should identify the opposite extraction.",
        )

        perfect_destroyed = _run_case(
            source_destroyed=True,
            kit_model_id=int(module.ModelID.Perfect_Salvage_Kit.value),
            target_component=True,
            opposite_component=False,
        )
        _expect(not perfect_destroyed.success, "Perfect Kit source destruction must remain a hard failure.")
        _expect("Perfect Salvage Kit" in perfect_destroyed.reason, "Perfect Kit destruction should be explicit.")

        expert_destroyed = _run_case(
            source_destroyed=True,
            kit_model_id=int(module.ModelID.Expert_Salvage_Kit.value),
            target_component=True,
            opposite_component=False,
        )
        _expect(
            expert_destroyed.success and expert_destroyed.status == "processed",
            "Non-perfect source destruction may succeed only with the selected component delta.",
        )

        expert_destroyed_opposite = _run_case(
            source_destroyed=True,
            kit_model_id=int(module.ModelID.Expert_Salvage_Kit.value),
            target_component=True,
            opposite_component=True,
        )
        _expect(
            not expert_destroyed_opposite.success,
            "Non-perfect source destruction with an opposite component delta must fail.",
        )
        _expect(
            "unselected armor upgrade was also extracted" in expert_destroyed_opposite.reason,
            "Destroyed-source opposite extraction should remain explicit.",
        )
    finally:
        module.Routines.Yield.wait = original_wait
        fixture["restore"]()


def _test_armor_upgrade_named_frames_preserve_rune_and_insignia_verification(module) -> None:
    expected, rune, insignia = _make_armor_upgrade_fixture(module)
    cases = (
        (rune, insignia, _FakeSalvageMode.Prefix, 8701),
        (insignia, rune, _FakeSalvageMode.Suffix, 8702),
    )
    for target, remaining, expected_mode, extracted_item_id in cases:
        state = _FakeSlotSalvageState(item_id=expected.item_id)
        restore_runtime = _install_fake_slot_salvage_runtime(module, state)
        original_wait = module.Routines.Yield.wait
        try:
            widget = _make_widget(module)
            reserved_item_ids: set[int] = set()

            def _start(item_id: int, kit_id: int, attempt: int):
                state.events.append(("start", int(item_id), int(kit_id), int(attempt)))
                state.options_open = True
                if False:
                    yield None
                return True

            def _capture_snapshot(item_id: int, *, allow_no_upgrades: bool = False):
                _expect(int(item_id) == expected.item_id, "Armor snapshot should remain bound to its source item.")
                if not any(event[0] == "confirm" for event in state.events):
                    return expected, ""
                return (
                    module.ArmorUpgradeSnapshot(
                        item_id=expected.item_id,
                        model_id=expected.model_id,
                        item_type_id=expected.item_type_id,
                        name=expected.name,
                        raw_modifiers=remaining.signature,
                        upgrades=(remaining,),
                    ),
                    "",
                )

            def _component_quantities(identity):
                if identity != target or not any(event[0] == "confirm" for event in state.events):
                    return {}
                return {extracted_item_id: 1}

            def _wait(milliseconds: int):
                state.events.append(("wait", int(milliseconds)))
                yield int(milliseconds)

            widget._queue_salvage_start = _start
            widget._capture_armor_upgrade_snapshot = _capture_snapshot
            widget._capture_standalone_armor_upgrade_component_quantities = _component_quantities
            widget._validate_inventory_shortcut_salvage_kit = lambda kit_id, **_kwargs: (int(kit_id), "")
            widget._get_salvage_kit_model_id = lambda _kit_id: int(module.ModelID.Perfect_Salvage_Kit.value)
            widget._get_inventory_item_ids = lambda: [expected.item_id]
            widget._reserve_execute_item_ids = lambda item_ids: reserved_item_ids.update(
                int(item_id) for item_id in item_ids
            )
            module.Routines.Yield.wait = _wait

            bridge = module._MerchantRulesArmorUpgradeSalvageBridge(owner=widget)
            result = _drain_generator_return(
                bridge.salvage_exact_armor_upgrade(
                    expected,
                    target,
                    preferred_kit_id=777,
                    timeout_ms=500,
                )
            )

            _expect(result.success and result.status == "processed", f"{target.semantic_kind} extraction should succeed.")
            _expect(state.selected_mode == expected_mode, f"{target.semantic_kind} should use its named fixed option.")
            _expect(
                extracted_item_id in result.reserved_item_ids and extracted_item_id in reserved_item_ids,
                f"{target.semantic_kind} extraction should verify and reserve the new standalone component.",
            )
            _expect(
                any(event[0] == "confirm" for event in state.events),
                f"{target.semantic_kind} should confirm only after snapshot and named-frame revalidation.",
            )
        finally:
            module.Routines.Yield.wait = original_wait
            restore_runtime()


def _test_armor_upgrade_named_frame_instance_change_blocks_confirmation(module) -> None:
    expected, rune, _insignia = _make_armor_upgrade_fixture(module)
    state = _FakeSlotSalvageState(item_id=expected.item_id)
    state.replace_frame_after_select = True
    restore_runtime = _install_fake_slot_salvage_runtime(module, state)
    original_wait = module.Routines.Yield.wait
    try:
        widget = _make_widget(module)

        def _start(*_args):
            state.options_open = True
            if False:
                yield None
            return True

        def _wait(milliseconds: int):
            yield int(milliseconds)

        widget._queue_salvage_start = _start
        widget._capture_armor_upgrade_snapshot = lambda *_args, **_kwargs: (expected, "")
        widget._capture_standalone_armor_upgrade_component_quantities = lambda *_args: {}
        widget._validate_inventory_shortcut_salvage_kit = lambda kit_id, **_kwargs: (int(kit_id), "")
        widget._get_salvage_kit_model_id = lambda _kit_id: int(module.ModelID.Perfect_Salvage_Kit.value)
        widget._get_inventory_item_ids = lambda: [expected.item_id]
        widget._reserve_execute_item_ids = lambda _item_ids: None
        module.Routines.Yield.wait = _wait

        bridge = module._MerchantRulesArmorUpgradeSalvageBridge(owner=widget)
        result = _drain_generator_return(
            bridge.salvage_exact_armor_upgrade(
                expected,
                rune,
                preferred_kit_id=777,
                timeout_ms=200,
            )
        )

        _expect(not result.success and result.status == "failed", "A replaced armor option frame must fail closed.")
        _expect("changed before confirmation" in result.reason, "The failure should identify option-instance drift.")
        _expect(any(event[0] == "select" for event in state.events), "The fixture should reach named-frame selection.")
        _expect(not any(event[0] == "confirm" for event in state.events), "Instance drift must prevent confirmation.")
        _expect(any(event[0] == "cancel" for event in state.events), "Instance drift should cancel the live popup safely.")
    finally:
        module.Routines.Yield.wait = original_wait
        restore_runtime()


def _test_specific_upgrade_ui_bridge_salvages_fixed_slots(module) -> None:
    cases = [
        (module.SALVAGE_OPTION_PREFIX, _FakeExactSlot.Prefix, _FakeSalvageMode.Prefix, "Cruel"),
        (module.SALVAGE_OPTION_SUFFIX, _FakeExactSlot.Suffix, _FakeSalvageMode.Suffix, "OfDefense"),
        (
            module.SALVAGE_OPTION_INSCRIPTION,
            _FakeExactSlot.Inscription,
            _FakeSalvageMode.Inscription,
            "AptitudeNotAttitude",
        ),
    ]
    for option, slot, mode, expected_upgrade in cases:
        state = _FakeSlotSalvageState()
        state.upgrades[slot] = expected_upgrade
        bridge, restore = _prepare_slot_salvage_bridge(module, state)
        try:
            result = _drain_generator_return(
                bridge.salvage_exact_upgrade(
                    state.item_id,
                    option,
                    expected_upgrade=expected_upgrade,
                    preferred_kit_id=777,
                    timeout_ms=500,
                )
            )
            event_names = [str(event[0]) for event in state.events]
            _expect(result.success and result.status == "processed", f"{option} should complete through fixed-slot UI.")
            _expect(state.selected_mode == mode, f"{option} should select only its matching fixed salvage mode.")
            _expect(slot not in state.upgrades, f"{option} should be verified absent from its physical slot.")
            _expect(
                event_names.index("select") < event_names.index("wait") < event_names.index("confirm"),
                "Exact-slot selection and confirmation must be separated by a yielded update cycle.",
            )
            _expect("cancel" not in event_names, "Successful exact-slot extraction should not cancel.")
        finally:
            restore()


def _test_specific_upgrade_ui_bridge_ignores_inactive_existing_frames(module) -> None:
    state = _FakeSlotSalvageState()
    state.inactive_frames_exist = True
    state.upgrades[_FakeExactSlot.Inscription] = "ForgetMeNot"
    bridge, restore = _prepare_slot_salvage_bridge(module, state)
    try:
        available, reason = bridge.is_available()
        _expect(available and reason == "", "The active-state UI capabilities should load.")
        _expect(
            module.Frame(module.FrameId.SalvageWindow.Options).exists,
            "The fixture should expose allocated named options frames.",
        )
        _expect(
            bridge._get_active_salvage_popup() is None,
            "Existing frames under an inactive popup hierarchy must not count as active.",
        )

        result = _drain_generator_return(
            bridge.salvage_exact_upgrade(
                state.item_id,
                module.SALVAGE_OPTION_INSCRIPTION,
                expected_upgrade="ForgetMeNot",
                preferred_kit_id=777,
                timeout_ms=500,
            )
        )

        _expect(result.success and result.status == "processed", "Inactive allocated frames must not block salvage.")
        _expect(state.events and state.events[0][0] == "start", "Normal salvage should start without a stale cancel.")
        _expect(not any(event[0] == "cancel" for event in state.events), "Inactive frames must never be cancelled.")
    finally:
        restore()


