def _test_specific_upgrade_ui_bridge_rejects_current_materials_warning(module) -> None:
    cases = (
        (_FakeExactSlot.Prefix, module.SALVAGE_OPTION_PREFIX, "Cruel"),
        (_FakeExactSlot.Suffix, module.SALVAGE_OPTION_SUFFIX, "OfDefense"),
        (_FakeExactSlot.Inscription, module.SALVAGE_OPTION_INSCRIPTION, "AptitudeNotAttitude"),
    )
    for exact_slot, selected_option, expected_upgrade in cases:
        for warning_before_start in (True, False):
            state = _FakeSlotSalvageState()
            state.upgrades[exact_slot] = expected_upgrade
            state.current_warning = warning_before_start
            state.current_warning_on_start = not warning_before_start
            bridge, restore = _prepare_slot_salvage_bridge(module, state)
            try:
                result = _drain_generator_return(
                    bridge.salvage_exact_upgrade(
                        state.item_id,
                        selected_option,
                        expected_upgrade=expected_upgrade,
                        preferred_kit_id=777,
                        timeout_ms=200,
                    )
                )
                _expect(not result.success, "The Materials warning must fail exact extraction.")
                _expect(("cancel",) in state.events, "The Materials warning must be cancelled safely.")
                _expect(("materials_yes",) not in state.events, "Exact extraction must never accept the Materials warning.")
                started = any(event[0] == "start" for event in state.events)
                _expect(
                    started is not warning_before_start,
                    "A pre-active warning must block before start; a warning created during extraction must fail afterward.",
                )
                _expect(not any(event[0] == "select" for event in state.events), "The warning must not fall back to another slot.")
                _expect(not any(event[0] == "confirm" for event in state.events), "The warning must not be confirmed.")
            finally:
                restore()


