def _test_crossed_item_names_fall_back_without_affecting_rule_identity(module) -> None:
    widget = _make_widget(module)
    widget.catalog_by_model_id = {
        925: {"model_id": 925, "name": "Bolt of Cloth", "material_type": "common", "priority": 1},
        7777: {"model_id": 7777, "name": "Jade Bracelet", "item_type": "Trophy", "priority": 1},
        19131: {"model_id": 19131, "name": "Radiant Insignia", "item_type": "Rune_Mod", "priority": 1},
    }
    widget.catalog_alias_to_model_ids = {
        module._normalize_catalog_search_text("Bolt of Cloth"): [925],
        module._normalize_catalog_search_text("Jade Bracelet"): [7777],
        module._normalize_catalog_search_text("Jade Bracelets"): [7777],
        module._normalize_catalog_search_text("Radiant Insignia"): [19131],
    }

    crossed_entry = module.ExecutionPlanEntry(
        action_type="sell",
        merchant_type=module.MERCHANT_TYPE_MATERIALS,
        label="3 Jade Bracelets",
        quantity=250,
        state=module.PLAN_STATE_WILL_EXECUTE,
        model_id=925,
    )
    fallback_label = widget._format_preview_item_label(crossed_entry)
    _expect("Bolt of Cloth" in fallback_label and "Jade" not in fallback_label, "Preview should replace a crossed cached name with the current model's catalog label.")

    material = _make_item(module, item_id=50, model_id=925, name="3 Jade Bracelets", quantity=250, is_material=True)
    planned_materials = widget._plan_material_sales([material], {50: 250}, 0)
    _expect(
        len(planned_materials) == 1
        and planned_materials[0].item_id == 50
        and planned_materials[0].model_id == 925
        and planned_materials[0].merchant_type == module.MERCHANT_TYPE_MATERIALS,
        "Material matching and destination should remain based on item ID, model, and type rather than a crossed name.",
    )
    _expect("Bolt of Cloth" in planned_materials[0].label, "Planned material labels should use the reliable model catalog when the runtime name contradicts it.")

    rune_identifier = "Radiant Insignia"
    widget.rune_names[rune_identifier] = "Radiant Insignia"
    rune_item = _make_item(
        module,
        item_id=51,
        model_id=19131,
        name="250 Bolts of Cloth",
        standalone_kind=module.RUNE_STANDALONE_KIND,
        rune_identifiers=[rune_identifier],
    )
    rune_rule = module.SellRule(
        enabled=True,
        kind=module.SELL_KIND_RUNE_TRADER_TARGET,
        rune_sell_targets=[module.RuneSellTarget(identifier=rune_identifier, keep_count=0)],
    )
    plan = module.PlanResult()
    widget._plan_rune_sell_target_sales(
        plan,
        [rune_item],
        rune_rule,
        0,
        set(),
        {module.MERCHANT_TYPE_RUNE_TRADER: (1.0, 1.0)},
    )
    _expect(
        len(plan.rune_trader_sales) == 1
        and plan.rune_trader_sales[0].expected_rune_identifiers == (rune_identifier,),
        "Exact rune matching should remain based on modifier identity even when the display name is crossed.",
    )
    _expect(plan.rune_trader_sales[0].label == "Radiant Insignia", "Exact rune Preview rows should use the modifier/catalog label, not the crossed item name.")


