        _expect(coords[module.MERCHANT_TYPE_MERCHANT] == (-2750.0, 731.0), "Resolution should search from the fresh player-agent coordinates.")
        _expect(coords[module.MERCHANT_TYPE_MATERIALS] is None, "An absent authoritative Material Trader match should fail closed immediately.")
