def _test_cleanup_keep_out_remains_model_wide_for_scoped_targets(module) -> None:
    widget = _make_widget(module)
    dust_model_id, items = _make_dust_and_koi_collision_items(module)
    widget.cleanup_blacklist_model_ids = [dust_model_id]
    widget.cleanup_targets = [
        module.CleanupTarget(
            model_id=dust_model_id,
            keep_on_character=0,
            scope=module.CLEANUP_TARGET_SCOPE_COMMON_MATERIAL,
        ),
        module.CleanupTarget(
            model_id=dust_model_id,
            keep_on_character=0,
            scope=module.CLEANUP_TARGET_SCOPE_EXACT,
        ),
    ]

    plan = _build_cleanup_plan_for_items(module, widget, items)

    _expect(not _cleanup_deposit_transfers(module, plan), "Keep Out should remain model-wide across scoped deposit targets.")
    _expect(
        sum(1 for entry in plan.entries if "Skipped by deposit keep-out." in str(entry.reason)) == 2,
        "Keep Out should document that both the material and exact scoped model-929 deposits were blocked.",
    )


def _test_linked_protected_deposit_keep_out_unaffected_by_scoped_targets(module) -> None:
    widget = _make_widget(module)
