def _test_inventory_item_log_label_avoids_stale_cached_names(module) -> None:
    widget = _make_widget(module)
    widget.catalog_by_model_id = {
        1914: {
            "model_id": 1914,
            "name": "Hypnotic Staff",
            "item_type": "Staff",
            "source": "test",
            "priority": 1,
        },
        2992: {
            "model_id": 2992,
            "name": "Salvage Kit",
            "item_type": "kit",
            "source": "test",
            "priority": 1,
        },
    }
    widget.catalog_alias_to_model_ids = {
        module._normalize_catalog_search_text("Hypnotic Staff"): [1914],
        module._normalize_catalog_search_text("Salvage Kit"): [2992],
    }

    stale_weapon = _make_item(
        module,
        item_id=104,
        model_id=1914,
        name='<c=@ItemCommon>Salvage Kit</c>',
        item_type_id=int(module.ItemType.Staff),
        item_type_name="Staff",
        is_weapon_like=True,
    )
    stale_label = widget._format_inventory_item_log_label(stale_weapon)
    _expect(
        stale_label == "Hypnotic Staff (1914)",
        "Salvage logs should fall back to the current model label when a cached name belongs to another model.",
    )

    real_kit = _make_item(
        module,
        item_id=105,
        model_id=2992,
        name='<c=@ItemCommon>Salvage Kit</c>',
        item_type_id=int(module.ItemType.Salvage),
        item_type_name="Salvage",
    )
    _expect(
        widget._format_inventory_item_log_label(real_kit) == '<c=@ItemCommon>Salvage Kit</c>',
        "Salvage logs should keep a runtime name when it matches the current model.",
    )

    generated_weapon = _make_item(
        module,
        item_id=106,
        model_id=1914,
        name="Sundering Hypnotic Staff of Fortitude",
        item_type_id=int(module.ItemType.Staff),
        item_type_name="Staff",
        is_weapon_like=True,
    )
    _expect(
        widget._format_inventory_item_log_label(generated_weapon) == "Sundering Hypnotic Staff of Fortitude",
        "Salvage logs should keep unknown generated weapon names instead of over-normalizing them.",
    )


def _test_trader_execution_revalidates_item_model_quantity_and_modifier_identity(module) -> None:
    widget = _make_widget(module)
    live_records: dict[int, dict[str, object]] = {}
    sold_item_ids: list[int] = []
    original_trading = getattr(module.GLOBAL_CACHE, "Trading", None)
    merchant_yield = module.Routines.Yield.Merchant
    had_wait_for_quote = hasattr(merchant_yield, "_wait_for_quote")
    original_wait_for_quote = getattr(merchant_yield, "_wait_for_quote", None)
    had_wait_for_stack_drop = hasattr(merchant_yield, "_wait_for_stack_quantity_drop")
    original_wait_for_stack_drop = getattr(merchant_yield, "_wait_for_stack_quantity_drop", None)
    original_wait = module.Routines.Yield.wait

    def _live_item(item_id: int, *, include_runtime_name: bool = True):
        record = live_records.get(int(item_id))
        if record is None:
            return None
        return _make_item(
            module,
            item_id=int(record.get("item_id", item_id)),
            model_id=int(record.get("model_id", 0)),
            name=str(record.get("name", "Crossed Runtime Label")) if include_runtime_name else f"Model {int(record.get('model_id', 0))}",
            quantity=int(record.get("quantity", 0)),
            is_material=bool(record.get("is_material", False)),
            standalone_kind=str(record.get("standalone_kind", "")),
            rune_identifiers=list(record.get("rune_identifiers", [])),
        )

    def _wait_for_quote(*_args, **_kwargs):
        if False:
            yield None
        return 100

    def _wait_for_stack_drop(item_id, _previous_quantity, **_kwargs):
        raise AssertionError(
            f"Merchant Rules should not use the stale item-ID-only quantity waiter for sale completion: {item_id}"
        )
        yield None

    def _wait(*_args, **_kwargs):
        if False:
            yield None

    def _sell_item(item_id: int, _quoted_value: int) -> None:
        safe_item_id = int(item_id)
        sold_item_ids.append(safe_item_id)
        record = live_records[safe_item_id]
        decrement = 10 if bool(record.get("is_material", False)) else 1
        record["quantity"] = max(0, int(record.get("quantity", 0)) - decrement)

    material_sale = module.PlannedMaterialSale(
        merchant_type=module.MERCHANT_TYPE_MATERIALS,
        item_id=10,
        model_id=925,
        label="Bolt of Cloth",
        batches_to_sell=1,
        quantity_to_sell=10,
        batch_size=10,
    )
    rune_sale = module.PlannedTraderSale(
        item_id=20,
        model_id=19131,
        label="Radiant Insignia",
        expected_rune_identifiers=("Radiant Insignia",),
    )

    try:
        widget._get_inventory_item_ids = lambda: [item_id for item_id, record in live_records.items() if int(record.get("quantity", 0)) > 0]
        widget._build_inventory_item_info = _live_item
        module.GLOBAL_CACHE.Trading = types.SimpleNamespace(
            Trader=types.SimpleNamespace(
                RequestSellQuote=lambda *_args, **_kwargs: None,
                SellItem=_sell_item,
            )
        )
        merchant_yield._wait_for_quote = _wait_for_quote
        merchant_yield._wait_for_stack_quantity_drop = _wait_for_stack_drop
        module.Routines.Yield.wait = _wait

        live_records[10] = {"item_id": 11, "model_id": 925, "quantity": 10, "is_material": True}
        id_mismatch = _drain_generator_return(widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999]))
        _expect(id_mismatch.unavailable == 1 and not sold_item_ids, "Material execution should abort before quoting when the reacquired item ID differs.")

        live_records[10] = {"item_id": 10, "model_id": 9999, "quantity": 10, "is_material": True}
        model_mismatch = _drain_generator_return(widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999]))
        _expect(model_mismatch.unavailable == 1 and not sold_item_ids, "Material execution should abort when the current model differs from Preview.")

        live_records[20] = {
            "item_id": 20,
            "model_id": 19131,
            "quantity": 1,
            "standalone_kind": module.RUNE_STANDALONE_KIND,
            "rune_identifiers": ["Blessed Insignia"],
        }
        modifier_mismatch = _drain_generator_return(widget._sell_planned_trader_items((2.0, 2.0), [rune_sale], trader_items=[999]))
        _expect(modifier_mismatch.unavailable == 1 and not sold_item_ids, "Rune execution should abort when the exact current modifier identity changes.")

        live_records[10] = {"item_id": 10, "model_id": 925, "quantity": 10, "is_material": True}
        live_records[20] = {
            "item_id": 20,
            "model_id": 19131,
            "quantity": 1,
            "standalone_kind": module.RUNE_STANDALONE_KIND,
            "rune_identifiers": ["Radiant Insignia"],
        }
        material_outcome = _drain_generator_return(widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999]))
        rune_outcome = _drain_generator_return(widget._sell_planned_trader_items((2.0, 2.0), [rune_sale], trader_items=[999]))
        _expect(
            sold_item_ids == [10, 20]
            and material_outcome.completed == 1
            and rune_outcome.completed == 1,
            "Sales should proceed only when item ID, model, quantity, type, and exact modifier identity still match.",
        )
    finally:
        module.GLOBAL_CACHE.Trading = original_trading
        if had_wait_for_quote:
            merchant_yield._wait_for_quote = original_wait_for_quote
        else:
            delattr(merchant_yield, "_wait_for_quote")
        if had_wait_for_stack_drop:
            merchant_yield._wait_for_stack_quantity_drop = original_wait_for_stack_drop
        else:
            delattr(merchant_yield, "_wait_for_stack_quantity_drop")
        module.Routines.Yield.wait = original_wait


def _test_trader_post_sale_completion_handles_disappearance_safely(module) -> None:
    widget = _make_widget(module)
    live_records: dict[int, dict[str, object]] = {}
    sold_item_ids: list[int] = []
    debug_lines: list[str] = []
    sale_behavior: dict[str, object] = {"callback": None}
    original_trading = getattr(module.GLOBAL_CACHE, "Trading", None)
    merchant_yield = module.Routines.Yield.Merchant
    had_wait_for_quote = hasattr(merchant_yield, "_wait_for_quote")
    original_wait_for_quote = getattr(merchant_yield, "_wait_for_quote", None)
    original_wait = module.Routines.Yield.wait

    def _live_item(item_id: int, *, include_runtime_name: bool = True):
        record = live_records.get(int(item_id))
        if record is None or not bool(record.get("present", True)):
            return None
        return _make_item(
            module,
            item_id=int(record.get("item_id", item_id)),
            model_id=int(record.get("model_id", 0)),
            name=str(record.get("name", "Runtime Label")) if include_runtime_name else f"Model {int(record.get('model_id', 0))}",
            quantity=int(record.get("quantity", 0)),
            is_material=bool(record.get("is_material", False)),
            standalone_kind=str(record.get("standalone_kind", "")),
            rune_identifiers=list(record.get("rune_identifiers", [])),
        )

    def _wait_for_quote(*_args, **_kwargs):
        if False:
            yield None
        return 100

    def _wait(*_args, **_kwargs):
        if False:
            yield None

    def _sell_item(item_id: int, _quoted_value: int) -> None:
        safe_item_id = int(item_id)
        sold_item_ids.append(safe_item_id)
        callback = sale_behavior.get("callback")
        if callable(callback):
            callback(safe_item_id)

    def _set_material(quantity: int) -> None:
        live_records.clear()
        live_records[10] = {
            "present": True,
            "item_id": 10,
            "model_id": 925,
            "quantity": int(quantity),
            "is_material": True,
        }

    def _set_rune() -> None:
        live_records.clear()
        live_records[20] = {
            "present": True,
            "item_id": 20,
            "model_id": 19131,
            "quantity": 1,
            "standalone_kind": module.RUNE_STANDALONE_KIND,
            "rune_identifiers": ["Radiant Insignia"],
        }

    material_sale = module.PlannedMaterialSale(
        merchant_type=module.MERCHANT_TYPE_MATERIALS,
        item_id=10,
        model_id=925,
        label="Bolt of Cloth",
        batches_to_sell=1,
        quantity_to_sell=10,
        batch_size=10,
    )
    rune_sale = module.PlannedTraderSale(
        item_id=20,
        model_id=19131,
        label="Radiant Insignia",
        expected_rune_identifiers=("Radiant Insignia",),
    )

    try:
        widget._get_inventory_item_ids = lambda: [
            item_id
            for item_id, record in live_records.items()
            if bool(record.get("present", True))
        ]
        widget._build_inventory_item_info = _live_item
        widget._debug_log = lambda message: debug_lines.append(str(message))
        module.GLOBAL_CACHE.Trading = types.SimpleNamespace(
            Trader=types.SimpleNamespace(
                RequestSellQuote=lambda *_args, **_kwargs: None,
                SellItem=_sell_item,
            )
        )
        merchant_yield._wait_for_quote = _wait_for_quote
        module.Routines.Yield.wait = _wait

        _set_rune()
        sold_item_ids.clear()
        debug_lines.clear()
        sale_behavior["callback"] = lambda item_id: live_records.pop(item_id, None)
        rune_outcome = _drain_generator_return(
            widget._sell_planned_trader_items(
                (2.0, 2.0),
                [rune_sale],
                phase_label="Rune disappearance",
                trader_items=[999],
            )
        )
        _expect(
            rune_outcome.completed == 1
            and rune_outcome.timeout_failures == 0
            and rune_outcome.unavailable == 0
            and sold_item_ids == [20],
            "A one-item rune or insignia disappearing after sale should complete exactly once without another sale request.",
        )
        _expect(
            any("Rune disappearance: completed=1/1" in line and "quantity_failures=0" in line for line in debug_lines),
            "The rune disappearance summary should report completed=1/1 and quantity_failures=0.",
        )

        _set_material(10)
        sold_item_ids.clear()
        debug_lines.clear()
        sale_behavior["callback"] = lambda item_id: live_records.pop(item_id, None)
        full_material_outcome = _drain_generator_return(
            widget._sell_planned_materials(
                (1.0, 1.0),
                [material_sale],
                phase_label="Material disappearance",
                trader_items=[999],
            )
        )
        _expect(
            full_material_outcome.completed == 1
            and full_material_outcome.timeout_failures == 0
            and full_material_outcome.unavailable == 0
            and sold_item_ids == [10],
            "A complete material stack disappearing after its final batch should complete exactly once.",
        )
        _expect(
            any("Material disappearance: completed=1/1" in line and "quantity_failures=0" in line for line in debug_lines),
            "The complete material disappearance summary should report completed=1/1 and quantity_failures=0.",
        )

        _set_material(20)
        sold_item_ids.clear()
        sale_behavior["callback"] = lambda item_id: live_records[item_id].update(quantity=10)
        partial_material_outcome = _drain_generator_return(
            widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999])
        )
        _expect(
            partial_material_outcome.completed == 1
            and partial_material_outcome.timeout_failures == 0
            and live_records[10]["quantity"] == 10,
            "A partial material sale should complete only when the same item remains with the exact expected lower quantity.",
        )

        _set_material(20)
        sold_item_ids.clear()
        sale_behavior["callback"] = lambda item_id: live_records.pop(item_id, None)
        missing_partial_outcome = _drain_generator_return(
            widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999])
        )
        _expect(
            missing_partial_outcome.completed == 0
            and missing_partial_outcome.timeout_failures == 1
            and missing_partial_outcome.unavailable == 0
            and sold_item_ids == [10],
            "A missing material item must remain a quantity failure when ten units were expected to remain.",
        )

        _set_material(10)
        sold_item_ids.clear()
        sale_behavior["callback"] = lambda _item_id: None
        unchanged_outcome = _drain_generator_return(
            widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999])
        )
        _expect(
            unchanged_outcome.completed == 0
            and unchanged_outcome.timeout_failures == 1
            and unchanged_outcome.unavailable == 0
            and sold_item_ids == [10],
            "An unchanged quantity through the bounded wait should remain a real quantity failure.",
        )

        _set_material(10)
        sold_item_ids.clear()
        sale_behavior["callback"] = lambda item_id: live_records[item_id].update(model_id=9999, quantity=0)
        reused_id_outcome = _drain_generator_return(
            widget._sell_planned_materials((1.0, 1.0), [material_sale], trader_items=[999])
        )
        _expect(
            reused_id_outcome.completed == 0
            and reused_id_outcome.timeout_failures == 0
            and reused_id_outcome.unavailable == 1,
            "A reused item ID with a changed model should produce an identity failure rather than sale success.",
        )

        _set_rune()
        sold_item_ids.clear()
        sale_behavior["callback"] = lambda item_id: live_records[item_id].update(
            quantity=0,
            rune_identifiers=["Blessed Insignia"],
        )
        changed_modifier_outcome = _drain_generator_return(
            widget._sell_planned_trader_items((2.0, 2.0), [rune_sale], trader_items=[999])
        )
        _expect(
            changed_modifier_outcome.completed == 0
            and changed_modifier_outcome.timeout_failures == 0
            and changed_modifier_outcome.unavailable == 1,
            "A changed rune or insignia modifier after sale should produce an identity failure.",
        )

        two_batch_sale = replace(material_sale, batches_to_sell=2, quantity_to_sell=20)
        _set_material(20)
        sold_item_ids.clear()

        def _sell_one_batch(item_id: int) -> None:
            remaining = int(live_records[item_id]["quantity"]) - 10
            if remaining <= 0:
                live_records.pop(item_id, None)
            else:
                live_records[item_id]["quantity"] = remaining

        sale_behavior["callback"] = _sell_one_batch
        two_batch_outcome = _drain_generator_return(
            widget._sell_planned_materials((1.0, 1.0), [two_batch_sale], trader_items=[999])
        )
        _expect(
            two_batch_outcome.completed == 2
            and two_batch_outcome.timeout_failures == 0
            and sold_item_ids == [10, 10],
            "A final-batch disappearance should complete the two planned trades without issuing a duplicate third sale.",
        )
    finally:
        module.GLOBAL_CACHE.Trading = original_trading
        if had_wait_for_quote:
            merchant_yield._wait_for_quote = original_wait_for_quote
        else:
            delattr(merchant_yield, "_wait_for_quote")
        module.Routines.Yield.wait = original_wait


def _test_display_sorting_helpers_and_summaries_are_case_insensitive(module) -> None:
    widget = _make_widget(module)
    _seed_display_sort_fixture(widget)

    _expect(
        widget._sort_model_ids_for_display([300, 100, 200, 400]) == [100, 400, 200, 300],
        "Display sorting for selected model-id lists should be alphabetical by displayed label with a stable fallback.",
    )
    _expect(
        [
            entry.model_id
            for entry in widget._sort_targets_by_model_label_for_display(
                [
                    module.WeaponRequirementRule(model_id=300, min_requirement=1, max_requirement=8),
                    module.WeaponRequirementRule(model_id=100, min_requirement=1, max_requirement=8),
                    module.WeaponRequirementRule(model_id=200, min_requirement=1, max_requirement=8),
                ]
            )
        ]
        == [100, 200, 300],
        "Display sorting for protected requirement rows should be alphabetical by model label without changing the stored rule order.",
    )
    _expect(
        widget._sort_identifiers_for_display(["mod_z", "mod_b", "mod_a"], widget._get_weapon_mod_label) == ["mod_a", "mod_b", "mod_z"],
        "Display sorting for protected identifiers should be case-insensitive and use the identifier as a stable fallback when names tie.",
    )
    _expect(
        [
            target.identifier
            for target in widget._sort_targets_by_identifier_label_for_display(
                [
                    module.RuneTraderTarget(identifier="rune_z", target_count=0, max_per_run=0),
                    module.RuneTraderTarget(identifier="rune_b", target_count=0, max_per_run=0),
                    module.RuneTraderTarget(identifier="rune_a", target_count=0, max_per_run=0),
                ],
                widget._get_rune_label,
            )
        ]
        == ["rune_a", "rune_b", "rune_z"],
        "Display sorting for rune-target tables should be case-insensitive and stable when labels tie.",
    )

    buy_stock_rule = module._normalize_buy_rule(
        module.BuyRule(
            enabled=True,
            kind=module.BUY_KIND_MERCHANT_STOCK,
            merchant_stock_targets=[
                module.MerchantStockTarget(model_id=300, target_count=0, max_per_run=0),
                module.MerchantStockTarget(model_id=100, target_count=0, max_per_run=0),
                module.MerchantStockTarget(model_id=200, target_count=0, max_per_run=0),
            ],
        )
    )
    buy_material_rule = module._normalize_buy_rule(
        module.BuyRule(
            enabled=True,
            kind=module.BUY_KIND_MATERIAL_TARGET,
            material_targets=[
                module.MaterialTarget(model_id=300, target_count=0, max_per_run=0),
                module.MaterialTarget(model_id=100, target_count=0, max_per_run=0),
                module.MaterialTarget(model_id=200, target_count=0, max_per_run=0),
            ],
        )
    )
    buy_rune_rule = module._normalize_buy_rule(
        module.BuyRule(
            enabled=True,
            kind=module.BUY_KIND_RUNE_TRADER_TARGET,
            rune_targets=[
                module.RuneTraderTarget(identifier="rune_z", target_count=0, max_per_run=0),
                module.RuneTraderTarget(identifier="rune_b", target_count=0, max_per_run=0),
                module.RuneTraderTarget(identifier="rune_a", target_count=0, max_per_run=0),
            ],
        )
    )
    sell_material_rule = module._normalize_sell_rule(
        module.SellRule(
            enabled=True,
            kind=module.SELL_KIND_COMMON_MATERIALS,
            whitelist_targets=[
                module.WhitelistTarget(model_id=300, keep_count=3),
                module.WhitelistTarget(model_id=100, keep_count=1),
                module.WhitelistTarget(model_id=200, keep_count=2),
            ],
        )
    )
    sell_item_rule = module._normalize_sell_rule(
        module.SellRule(
            enabled=True,
            kind=module.SELL_KIND_EXPLICIT_MODELS,
            whitelist_targets=[
                module.WhitelistTarget(model_id=300, keep_count=3),
                module.WhitelistTarget(model_id=100, keep_count=1),
                module.WhitelistTarget(model_id=200, keep_count=2),
            ],
        )
    )
    destroy_material_rule = module._normalize_destroy_rule(
        module.DestroyRule(
            enabled=True,
            kind=module.DESTROY_KIND_MATERIALS,
            whitelist_targets=[
                module.WhitelistTarget(model_id=300, keep_count=3),
                module.WhitelistTarget(model_id=100, keep_count=1),
                module.WhitelistTarget(model_id=200, keep_count=2),
            ],
        )
    )
    destroy_item_rule = module._normalize_destroy_rule(
        module.DestroyRule(
            enabled=True,
            kind=module.DESTROY_KIND_EXPLICIT_MODELS,
            whitelist_targets=[
                module.WhitelistTarget(model_id=300, keep_count=3),
                module.WhitelistTarget(model_id=100, keep_count=1),
                module.WhitelistTarget(model_id=200, keep_count=2),
            ],
        )
    )

    buy_stock_summary, buy_stock_ready = widget._get_buy_rule_summary(buy_stock_rule)
    buy_material_summary, buy_material_ready = widget._get_buy_rule_summary(buy_material_rule)
    buy_rune_summary, buy_rune_ready = widget._get_buy_rule_summary(buy_rune_rule)
    sell_material_summary, sell_material_ready = widget._get_sell_rule_summary(sell_material_rule)
    sell_item_summary, sell_item_ready = widget._get_sell_rule_summary(sell_item_rule)
    destroy_material_summary, destroy_material_ready = widget._get_destroy_rule_summary(destroy_material_rule)
    destroy_item_summary, destroy_item_ready = widget._get_destroy_rule_summary(destroy_item_rule)

    _expect(
        buy_stock_ready and buy_stock_summary == "3 stock target(s) | alpha, Bravo +1 more",
        "Collapsed buy stock summaries should use the same alphabetical display order as the expanded target table.",
    )
    _expect(
        buy_material_ready and buy_material_summary == "3 material target(s) | alpha, Bravo +1 more",
        "Collapsed buy material summaries should use the same alphabetical display order as the expanded target table.",
    )
    _expect(
        buy_rune_ready and buy_rune_summary == "3 target(s) | shared rune, Shared Rune +1 more",
        "Collapsed buy rune summaries should use the same alphabetical display order as the expanded target table.",
    )
    _expect(
        sell_material_ready and sell_material_summary == "3 material target(s) | alpha keep 1, Bravo keep 2 +1 more",
        "Collapsed sell material summaries should match the alphabetical order used by the expanded selected-materials table.",
    )
    _expect(
        sell_item_ready and sell_item_summary == "3 selected target(s) | alpha keep 1, Bravo keep 2 +1 more",
        "Collapsed sell explicit-item summaries should match the alphabetical order used by the expanded selected-items table.",
    )
    _expect(
        destroy_material_ready and destroy_material_summary == "3 material target(s) | alpha keep 1, Bravo keep 2 +1 more",
        "Collapsed destroy material summaries should match the alphabetical order used by the expanded selected-materials table.",
    )
    _expect(
        destroy_item_ready and destroy_item_summary == "3 selected target(s) | alpha keep 1, Bravo keep 2 +1 more",
        "Collapsed destroy explicit-item summaries should match the alphabetical order used by the expanded selected-items table.",
    )
    _expect(
        [target.model_id for target in buy_stock_rule.merchant_stock_targets] == [300, 100, 200],
        "Display-only summary sorting should not mutate the stored merchant-stock target order.",
    )
    _expect(
        [target.identifier for target in buy_rune_rule.rune_targets] == ["rune_z", "rune_b", "rune_a"],
        "Display-only summary sorting should not mutate the stored rune-target order.",
    )


def _test_display_sort_reads_preserve_saved_child_entry_order(module, temp_root: Path) -> None:
    widget = _make_widget(module)
    _seed_display_sort_fixture(widget)
    config_path = temp_root / "display_sort_preserves_saved_order.json"
    widget.config_path = str(config_path)

    widget.buy_rules = [
        module._normalize_buy_rule(
            module.BuyRule(
                enabled=True,
                kind=module.BUY_KIND_MERCHANT_STOCK,
                merchant_stock_targets=[
                    module.MerchantStockTarget(model_id=300, target_count=0, max_per_run=0),
                    module.MerchantStockTarget(model_id=100, target_count=0, max_per_run=0),
                    module.MerchantStockTarget(model_id=200, target_count=0, max_per_run=0),
                ],
            )
        ),
        module._normalize_buy_rule(
            module.BuyRule(
                enabled=True,
                kind=module.BUY_KIND_MATERIAL_TARGET,
                material_targets=[
                    module.MaterialTarget(model_id=300, target_count=0, max_per_run=0),
                    module.MaterialTarget(model_id=100, target_count=0, max_per_run=0),
                    module.MaterialTarget(model_id=200, target_count=0, max_per_run=0),
                ],
            )
        ),
        module._normalize_buy_rule(
            module.BuyRule(
                enabled=True,
                kind=module.BUY_KIND_RUNE_TRADER_TARGET,
                rune_targets=[
                    module.RuneTraderTarget(identifier="rune_z", target_count=0, max_per_run=0),
                    module.RuneTraderTarget(identifier="rune_b", target_count=0, max_per_run=0),
                    module.RuneTraderTarget(identifier="rune_a", target_count=0, max_per_run=0),
                ],
            )
        ),
    ]
    widget.sell_rules = [
        module._normalize_sell_rule(
            module.SellRule(
                enabled=True,
                kind=module.SELL_KIND_WEAPONS,
                blacklist_model_ids=[300, 100, 200],
                protected_weapon_requirement_rules=[
                    module.WeaponRequirementRule(model_id=300, min_requirement=1, max_requirement=8),
                    module.WeaponRequirementRule(model_id=100, min_requirement=1, max_requirement=9),
                    module.WeaponRequirementRule(model_id=200, min_requirement=1, max_requirement=10),
                ],
                protected_weapon_mod_identifiers=["mod_z", "mod_b", "mod_a"],
                rule_id="weapon_rule",
            )
        ),
        module._normalize_sell_rule(
            module.SellRule(
                enabled=True,
                kind=module.SELL_KIND_ARMOR,
                protected_rune_identifiers=["rune_z", "rune_b", "rune_a"],
                rule_id="armor_rule",
            )
        ),
        module._normalize_sell_rule(
            module.SellRule(
                enabled=True,
                kind=module.SELL_KIND_EXPLICIT_MODELS,
                whitelist_targets=[
                    module.WhitelistTarget(model_id=300, keep_count=3),
                    module.WhitelistTarget(model_id=100, keep_count=1),
                    module.WhitelistTarget(model_id=200, keep_count=2),
                ],
            )
        ),
    ]
    widget.destroy_rules = [
        module._normalize_destroy_rule(
            module.DestroyRule(
                enabled=True,
                kind=module.DESTROY_KIND_EXPLICIT_MODELS,
                whitelist_targets=[
                    module.WhitelistTarget(model_id=300, keep_count=3),
                    module.WhitelistTarget(model_id=100, keep_count=1),
                    module.WhitelistTarget(model_id=200, keep_count=2),
                ],
            )
        )
    ]
    widget.cleanup_targets = [
        module.CleanupTarget(model_id=300, keep_on_character=3),
        module.CleanupTarget(model_id=100, keep_on_character=1),
        module.CleanupTarget(model_id=200, keep_on_character=2),
    ]

    for buy_rule in widget.buy_rules:
        widget._get_buy_rule_summary(buy_rule)
    for sell_rule in widget.sell_rules:
        widget._get_sell_rule_summary(sell_rule)
    for destroy_rule in widget.destroy_rules:
        widget._get_destroy_rule_summary(destroy_rule)
    widget._sort_model_ids_for_display(widget.sell_rules[0].blacklist_model_ids)
    widget._sort_identifiers_for_display(widget.sell_rules[0].protected_weapon_mod_identifiers, widget._get_weapon_mod_label)

    _expect(widget._save_profile(), "Saving a profile after display-only sorting reads should still succeed.")
    saved_payload = json.loads(config_path.read_text(encoding="utf-8"))

    _expect(
        [entry["model_id"] for entry in saved_payload["buy_rules"][0]["merchant_stock_targets"]] == [300, 100, 200],
        "Display-only sorting must not change persisted merchant-stock target order.",
    )
    _expect(
        [entry["model_id"] for entry in saved_payload["buy_rules"][1]["material_targets"]] == [300, 100, 200],
        "Display-only sorting must not change persisted material-target order.",
    )
    _expect(
        [entry["identifier"] for entry in saved_payload["buy_rules"][2]["rune_targets"]] == ["rune_z", "rune_b", "rune_a"],
        "Display-only sorting must not change persisted rune-target order.",
    )
    _expect(
        saved_payload["sell_rules"][0]["blacklist_model_ids"] == [300, 100, 200],
        "Display-only sorting must not change persisted protected-model order.",
    )
    _expect(
        [entry["model_id"] for entry in saved_payload["sell_rules"][0]["protected_weapon_requirement_rules"]] == [300, 100, 200],
        "Display-only sorting must not change persisted protected-requirement order.",
    )
    _expect(
        saved_payload["sell_rules"][0]["protected_weapon_mod_identifiers"] == ["mod_z", "mod_b", "mod_a"],
        "Display-only sorting must not change persisted protected-weapon-mod order.",
    )
    _expect(
        saved_payload["sell_rules"][1]["protected_rune_identifiers"] == ["rune_z", "rune_b", "rune_a"],
        "Display-only sorting must not change persisted protected-rune order.",
    )
    _expect(
        [entry["model_id"] for entry in saved_payload["sell_rules"][2]["whitelist_targets"]] == [300, 100, 200],
        "Display-only sorting must not change persisted sell whitelist order.",
    )
    _expect(
        [entry["model_id"] for entry in saved_payload["destroy_rules"][0]["whitelist_targets"]] == [300, 100, 200],
        "Display-only sorting must not change persisted destroy whitelist order.",
    )
    _expect(
        [entry["model_id"] for entry in saved_payload["cleanup_targets"]] == [300, 100, 200],
        "Display-only sorting must not change persisted cleanup-target order.",
    )


def _test_rune_description_templates_resolve_for_tooltips(module) -> None:
    description = "+{arg2[8680]} {arg1[8680]} (Non-stacking)\n-{arg2[8408]} Health"
    modifiers = [
        {"Identifier": 8680, "Arg1": 35, "Arg2": 2, "Arg": 8962},
        {"Identifier": 8408, "Arg1": 0, "Arg2": 35, "Arg": 35},
    ]
    resolved = module._resolve_rune_description_template(description, modifiers)
    _expect(
        resolved == "+2 Critical Strikes (Non-stacking)\n-35 Health",
        "Rune tooltip descriptions should resolve attribute and health placeholders while preserving non-stacking text.",
    )


