        next(owned_generator)
        _expect(
            widget.merchant_rules_owned_work_count == 1 and events == ["started"],
            f"Remote {label} should remain owned while its handler is paused.",
        )
        _drain_generator_return(owned_generator)
        _expect(
            widget.merchant_rules_owned_work_count == 0 and events == ["started", "finished"],
            f"Remote {label} should release ownership only after its handler finishes.",
        )


